(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.9"]={"from":216,"a":[["\u0003ימכרו\u0004 האילנות הללו \u0003לעצים, וילקח\u0004 (תיקנה) \u0003בהן קרקע, והוא\u0004 הבעל \u0003אוכל פירות\u0004 וגוף הקרקע שייך לאשה. ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003והזקינו,\u0004 כלומר, שלא היו האילנות זקנים כשירשה אותם אלא שהזקינו במשך הזמן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ: \u0003לאו מי אוקימנא לההיא\u0004 \u0005[האם לא העמדנו,\u0006 והסברנו, כבר \u0005את\u0006 הברייתא \u0005ההיא]\u0006 במקומה \u0003כגון שנפלו לה\u0004 אותם הגפנים וזיתים \u0003בשדה אחרת\u0004 — בשדה שאינו שלה, שירושתה היתה רק אותם אילנות (ולא הקרקע), ואם כן הם הם הקרן, ואם יאכלו את דמיהם \u0003דקא כליא קרנא\u0004 \u0005[שכלתה הקרן]\u0006 ושם ודאי יש למכור אותם לעצים ולקנות בהם קרקע.","מסופר: \u0003ההוא שטרא דהוה כתיב ביה שנין סתמא\u0004 \u0005[שטר\u0006 משכון \u0005אחד היה כתוב בו\u0006 שהוא \u0005לשנים סתם]\u0006 מבלי לפרט לכמה שנים. \u0003מלוה אמר:\u0004 ל\u0003שלש\u0004 שנים, וה\u0003לוה אמר:\u0004 ל\u0003שתים.\u0004 ועד שהם מדיינים בדבר \u0003קדים\u0004 \u0005[הקדים]\u0006 ה\u0003מלוה ואכלינהו לפירי\u0004 \u0005[ואכל את הפירות]\u0006 מן השדה בשנה השלישית. והשאלה היא \u0003מי נאמן? רב יהודה אמר:\u0004 הרי כלל הוא ש\u0003קרקע בחזקת בעליה קיימא\u0004 \u0005[עומדת],\u0006 ולכן החזקה היא בידי בעל הקרקע־הלווה, והמלווה־בעל השטר הוא שצריך להביא ראיה. \u0003רב כהנא אמר: פירות בחזקת אוכליהן קיימי\u0004 \u0005[עומדים],\u0006 ולכן הדין עם המלווה.","ואומרים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב כהנא\u0004 ש\u0003אמר: פירות בחזקת אוכליהן קיימי.\u0004 ושואלים: \u0003והא קיימא לן דהלכתא כוותיה\u0004 \u0005[והרי מוחזק בידינו שהלכה כשיטתו]\u0006 של \u0003רב נחמן\u0004 ש\u0003אמר\u0004 בענין ספק בדבר שכירות בחודש העיבור: \u0003קרקע בחזקת בעליה עומדת,\u0004 ובעל הקרקע נחשב כמוחזק, ואם כן יש סתירה בין פסיקות הלכה אלה!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 — \u0003מילתא דלא עבידא לאיגלויי היא\u0004 \u0005[דבר שאינו עשוי להגלות הוא],\u0006 ששם היה הספק בענין עקרוני שאינו ניתן להתברר לעצמו כלל. \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003מילתא דעבידא לאיגלויי היא\u0004 \u0005[דבר שעשוי להגלות הוא],\u0006 שהרי בסופו של דבר יביאו את העדים שחתמו על השטר, והם יספרו מה היה כתוב בו, ולפי זה נפסוק הלכה, \u0003ואטרוחי בי דינא תרי זמני לא מטרחינן\u0004 \u0005[ולהטריח את בית הדין שתי פעמים אין מטריחים],\u0006 ולכן מניחים את הפירות ביד מי שאכלם, עד שיתברר כל הענין.","דיון אחר היה בשאלה דומה: קרקע שהיתה ממושכנת לחוב, ה\u0003מלוה אומר\u0004 של \u0003חמש\u0004 שנים היתה המשכנתא, וה\u0003לוה\u0004 שהוא בעל הקרקע \u0003אומר\u0004 של \u0003שלש\u0004 שנים בלבד היתה המשכנתא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה למלוה: \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003לי\u0004 את \u0003שטרך\u0004 ונראה מה כתוב בו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 המלוה ללווה: \u0003שטרא אירכס\u0004 \u0005השטר אבד\u0006 \u0003לי.\u0004 \u0003אמר רב יהודה:\u0004 ה\u0003מלוה נאמן.\u0004 ומדוע — \u0003מגו דאי בעי אמר\u0004 \u0005[מתוך שאם\u0006 היה \u0005רוצה\u0006 לשקר היה \u0005אומר]\u0006 שהקרקע \u0003לקוחה\u0004 (קנויה) \u0003היא בידי.\u0004 שהרי כיון שאין שטר משכנתא מצוי, והוא החזיק בקרקע שלוש שנים (שהם שנות חזקה) היה יכול לטעון שהקרקע שלו, ואם לא עשה כן — צריך להאמין לו במה שהוא טוען.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרב אשי: רב זביד ורב עוירא לא סבירא להו הא\u0004 \u0005[אינם סבורים כזו]\u0006 שאמר \u0003רב יהודה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003האי שטרא\u0004 \u0005[אותו שטר]\u0006 \u0003כיון דלגוביינא קאי\u0004 \u0005[שלגביה\u0006 הוא \u0005עומד]\u0006 — \u0003מיזהר זהיר ביה\u0004 \u0005[נזהר\u0006 הוא \u0005בו],\u0006 שהרי המלוה רוצה לקבל את הכסף שהלוה, ולא סביר להניח שאיבד שטר כזה, אלא \u0003ומיכבש\u0004 \u0005[ולכבוש,\u0006 להחביא\u0005]\u0006 \u0003הוא דכבשיה לשטריה\u0004 \u0005[שכבש את שטרו],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003אוכלה תרתין שנין יתירתא\u0004 \u0005[אוכל אותה,\u0006 את תנובת השדה \u0005שתי שנים יתירות].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אלא מעתה, האי\u0004 \u0005[אותו\u0006 סוג\u0005]\u0006 של \u0003משכנתא\u0004 שעושים ב\u0003סורא דכתבי הכי\u0004 \u0005[שכותבים\u0006 בה \u0005כך]:\u0006 \u0003\"במישלם שניא אלין תיפוק ארעא דא\u0004 \u0005[בהשלמת השנים הללו,\u0006 של המשכון \u0005תצא קרקע זו]\u0006 \u0003בלא כסף\u0004 ותחזור לבעליה. \u0003היכא דכבשיה\u0004 \u0005[היכן שכבשו,\u0006 הסתיר\u0005]\u0006 את \u0003שטר\u0004 ה\u0003משכנתא\u0004 \u0003ואמר: לקוחה\u0004 (קנויה) \u0003היא\u0004 הקרקע \u0003בידי, הכי נמי דמהימן\u0004 \u0005[כך גם כן תאמר שהוא נאמן]?!\u0006 \u0003וכי מתקני רבנן מילתא דאתי בה\u0004 \u0005[וכי מתקנים חכמים דבר\u0006 שיכול \u0005לבוא בו]\u0006 \u0003לידי פסידא\u0004 \u0005[הפסד]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם תקינו ליה רבנן דמרי ארעא יהיב טסקא וכרי כריא\u0004 \u0005[שם\u0006 במשכנתא בסורא, \u0005תיקנו לו חכמים שבעל הקרקע\u0006 הוא ש\u0005נותן,\u0006 משלם, \u0005את המיסים ו\u0006הוא \u0005כורה את התעלות],\u0006 שצריך לכרות כדי להשקות את השדה, ועל ידי כך נשמרת ומוכרת בעלותו.","ושואלים: \u0003ארעא דלית ליה כריא ולא יהיב טסקא מאי\u0004 \u0005[\u0006ב\u0005קרקע שאין בה\u0006 צורך תעלות \u0005ואינו נותן,\u0006 משלם, \u0005מיסים, מה]\u0006 יעשה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003איבעי ליה למחויי\u0004 \u0005[היה צריך למחות]\u0006 לפני שהגיע זמן החזקה ולהודיע שקרקע זו שלו היא! ושואלים: ואם \u0003לא אימחא\u0004 \u0005[מחה],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 אמר לו: אם כן \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא שהפסיד לעצמו]\u0006 שלא נקט באמצעי הזהירות הדרושים.","\u0003אריס אומר: למחצה ירדתי\u0004 לשדה זו, שהתנאים בינינו היו שאקבל אני חצי מן הפירות, \u0003ובעל הבית אומר: לשליש\u0004 בלבד \u0003הורדתיו, מי\u0004 מהם \u0003נאמן?\u0004 \u0003רב יהודה אמר: בעל הבית נאמן. רב נחמן אמר: הכל כמנהג המדינה,\u0004 שכיון שאין ההסכם הזה ברור ינהגו כפי שנוהגים אריסים באותו מקום.","\u0003סבור מינה לא פליגי\u0004 \u0005[חשבו\u0006 בתחילה שבעצם \u0005אין חולקים]\u0006 אלא מדברים במקרים שונים; \u0003הא באתרא דשקיל אריסא פלגא\u0004 \u0005[זה במקום שנוטל האריס חצי]\u0006 ואילו \u0003הא באתרא דשקיל אריסא תילתא\u0004 \u0005[זה במקום שנוטל האריס שליש]\u0006 — נאמן בעל הבית.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב מרי ברה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אביי: אפילו באתרא דשקיל אריסא פלגא פליגי\u0004 \u0005[במקום שנוטל\u0006 כרגיל \u0005האריס חצי חלוקים\u0006 הם\u0005],\u0006 ש\u0003רב יהודה אמר: בעל הבית נאמן,\u0004 גם אז, \u0003דאי בעי אמר\u0004 \u0005[שאם\u0006 היה \u0005רוצה\u0006 לשקר \u0005יאמר]:\u0006 \u0003שכירי ולקיטי הוא,\u0004 שאינו אריס כלל אלא רק שכיר שנשכר בסכום כסף מסויים, או לקיט המקבל עבודותיו אצלו, ואין לו כלל חלק מוגדר ביבול.","ובעיה אחרת: היה שדה משועבד כאחריות להלוואה, ומת הלווה ועבר השדה בירושה לבניו, ואותם \u0003יתומים אומרים: אנו השבחנו\u0004 בינתים את הקרקע, ולכן מגיע לנו חלק בקרקע לפני שבעל החוב נוטל אותה, \u0003ובעל\u0004 ה\u0003חוב אומר: אביכם השביח\u0004 ולכן שייכת לי הקרקע כמות שהיא, \u0003על מי\u0004 מהם \u0003להביא ראיה?\u0004"],["\u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003ר' חנינא למימר\u0004 \u0005[לומר]:\u0006 \u0003ארעא\u0004 \u0005[הקרקע]\u0006 \u0003בחזקת יתמי קיימא\u0004 \u0005[היתומים עומדת],\u0006 שהרי בידם היא עכשיו, ולכן \u0003על בעל\u0004 ה\u0003חוב להביא ראיה. אמר להו ההוא סבא\u0004 \u0005[להם זקן אחד],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: על היתומים להביא ראיה. מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003ארעא\u0004 \u0005[הקרקע],\u0006 \u0003כיון דלגוביינא קיימא\u0004 \u0005[שלגביה\u0006 היא \u0005עומדת]\u0006 — \u0003כמאן דגביא דמיא\u0004 \u0005[כמו ש\u0006היא \u0005גבויה נחשבת]\u0006 וכאילו היתה כבר ברשות בעל החוב, ולכן \u0003על היתומים להביא ראיה.\u0004","\u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 כעין זה לגבי האילן הנטוע סמוך לעיר, ששנינו שיש לקצוץ אותו, אלא שאם קדמה העיר לאילן — קוצץ בלי לשלם תמורתו, ואם הוא קדם לעיר — קוצץ אותו ומקבל תשלום עבורו. \u0003ספק זה קדם וספק זה קדם\u0004 — \u0003קוצץ ואינו נותן דמים.\u0004","\u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003כיון דלמיקץ קיימא\u0004 \u0005[ש\u0006אילן זה \u0005להקצץ\u0006 הוא \u0005עומד]\u0006 \u0003אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003אייתי\u0004 \u0005[הבא]\u0006 אתה \u0003ראיה ושקול\u0004 \u0005[וקח],\u0006 אף שהעץ עדיין ברשותו ולא נקצץ. \u0003הכא נמי, האי שטרא\u0004 \u0005[כאן גם כן,\u0006 שטר זה] \u0003כיון דלגוביינא קיימא\u0004 \u0005[שלגביה\u0006 וא \u0005עומד]\u0006 — \u0003כמאן דגביא דמיא\u0004 \u0005[כמו ש\u0006הוא \u0005גבוי נחשב]\u0006 \u0003ועל היתומים להביא ראיה\u0004","\u0003אייתו יתמי\u0004 \u0005[הביאו היתומים]\u0006 \u0003ראיה דאינהו אשבחו\u0004 \u0005[ש\u0006אכן \u0005הם\u0006 ש\u0005השביחו],\u0006 מה עושים? \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003ר' חנינא למימר\u0004 \u0005[לומר]:\u0006 \u0003כי מסלקינן להו\u0004 \u0005[כאשר מסלקים אנו אותם]\u0006 — \u0003בארעא מסלקינן להו\u0004 \u0005[מסלקים אותם בקרקע],\u0006 כלומר, נותנים להם חלק מן הקרקע דמי השבח.","ומעירים על כך: \u0003ולא היא\u0004 (אין כן הדבר), \u0003בדמי מסלקינן להו\u0004 \u0005[בכספים מסלקים אותם]\u0006 ואנו מסתמכים בכך על דברי \u0003רב נחמן.\u0004 ש\u0003אמר רב נחמן אמר שמואל: שלשה שמין\u0004 (מעריכים) \u0003להם את השבח\u0004 שהשביחו בקרקע, \u0003ומעלין אותן בדמים\u0004 (מחשיבים אותם בכסף) ולא בקרקע עצמה, \u0003ואלו הן: בכור לפשוט,\u0004 שהרי הבכור מקבל פי שניים בנחלת אביו, ואם השביחו הבנים את הקרקע המשותפת לפני שחלקו, אין לבכור זכות כפולה בשבח, אלא מתחלקים בנחלה כרגיל (ביחס של שני שליש ושליש), והבכור משלם לאחיו את חלקו היחסי בשבח שבחלק הנוסף בכסף (ולא בקרקע), והוא רבע מכלל השבח שעלה לחלקו.","\u0003ובעל חוב וכתובת אשה ליתומים,\u0004 שאם היתומים השביחו בנכסי אביהם ובא בעל החוב או האשה לגבות את המגיע להם — משלמים הם כסף ליתומים על מה שהשביחו, אבל לא קרקע. \u0003ו\u0004כן \u0003בעל חוב ללקוחות,\u0004 שאם מכר הלווה את הקרקע, והלקוחות החזיקו בינתיים את הקרקע והשביחוה — המלווה ששטרו קודם טורף מהם את הקרקע ומשלם להם את מה שהשביחו בכסף ולא בחלק מן הקרקע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: למימרא דסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003שמואל\u0004 כי \u0003בעל חוב\u0004 נותן את השבח \u0003ללקוחות? ומי אית ליה שבחא\u0004 \u0005[והאם יש לו שבח]\u0006 \u0003ללוקח\u0004 לדעת שמואל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 ש\u0003בעל חוב גובה\u0004 גם \u0003את השבח\u0004 ולא רק את גוף הקרקע! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאינו גובה הוא בשבח, הרי זה \u0003בשבח המגיע לכתפים,\u0004 בשבח שכבר הגיעה התוספת לדרגה כזו של גידול עד כדי שכבר יכולים לקחת אותו משם על כתפי הסבלים, \u0003כאן\u0004 — \u0003בשבח שאין מגיע לכתפים. והא\u0004 \u0005[והרי]\u0006 \u0003מעשים\u0004 היו \u0003בכל יום\u0004 במקרים כאלה, \u0003וקא מגבי\u0004 \u0005[והיה מגבה]\u0006 \u0003שמואל\u0004 לבעל חוב הכל, ו\u0003אפילו בשבח המגיע לכתפים!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דמסיק ביה\u0004 \u0005[שהיה נושה בו]\u0006 בלווה הראשון \u0003כשיעור ארעא ושבחא\u0004 \u0005[הקרקע והשבח\u0006 יחד\u0005]\u0006 ובכגון זה אינו מחזיר ללקוחות דבר, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דלא מסיק ביה\u0004 \u0005[שאינו נושא בו]\u0006 \u0003שיעור ארעא ושבחא\u0004 \u0005[קרקע והשבח],\u0006 ונמצא שמקבל יותר משמגיע לו, ואז משלם השבח ללקוחות.","ושואלים: \u0003וכי לא מסיק\u0004 \u0005[וכאשר אינו נושה]\u0006 בו \u0003שיעור ארעא ושבחא\u0004 \u0005[הקרקע והשבח],\u0006 \u0003דיהיב ליה זוזי\u0004 \u0005[שנותן לו כסף]\u0006 \u0003ללוקח ומסלק ליה\u0004 \u0005[אותו],\u0006 \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח\u0006 לשיטת \u0005מי שאומר]\u0006 שגם \u0003אי אית ליה זוזי\u0004 \u0005[אם יש לו\u0006 \u0003כסף]\u0004 \u0003ללוקח לא מצי מסלק ליה\u0004 \u0005[אינו יכול לסלק אותו]\u0006 את \u0003בעל\u0004 ה\u0003חוב\u0004 ולשלם לו את חובו בכסף, אלא יכול בעל חוב לגבות בקרקע, ולשיטה זו שיש למלוה זכות גמורה בקרקע עצמה — \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אית ליה זוזי\u0004 \u0005[\u0006ש\u0005אם יש לו כסף]\u0006 \u0003ללוקח מצי מסלק ליה\u0004 \u0005[יכול\u0006 וא \u0005לסלק אותו]\u0006 את \u0003בעל\u0004 ה\u0003חוב\u0004 בכספים ולהחזיק בקרקע, אם כן במקרה זה, \u0003ונימא ליה\u0004 \u0005[ושיאמר לו]\u0006 כך: \u0003אי הוו\u0004 \u0005[אם היו]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף מזומן\u0005]\u0006 \u0003הוה מסליקנא\u0004 \u0003לך מכולא ארעא\u0004 \u0005[הייתי מסלק אותך מכל הקרקע],\u0006 \u0003השתא דלית\u0004 \u0005[עכשיו שאין]\u0006 \u0003לי זוזי\u0004 \u0005[כסף]\u0006 עבור כל הקרקע, כיון שאתה צריך להחזיר לי כסף עבור השבח, על כל פנים \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי גריוא דארעא בארעאי\u0004 \u0005[חלקת אדמה בקרקע שלי]\u0006 כ\u0003שיעור שבחאי\u0004 \u0005[שבחי]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה \u0003כגון דשויא ניהליה\u0004 \u0005[ש\u0006החייב \u0005עשה לו\u0006 את הקרקע \u0005הזו]\u0006 \u0003אפותיקי,\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יהא לך פרעון אלא מזו\u0004 ולא מכל קרקע אחרת. ולכן רוצה בעל החוב לקבל את כל הקרקע כולה, שהרי שיעבודו רק על קרקע זו ואם יתברר שיש עוד תביעות בידו לא יוכל לקבלן ממקום אחר.","\u0003המקבל שדה מחבירו לשבוע אחד\u0004 (למשך זמן של שבע שנים רצופות, שמיטה אחת) \u0003בשבע מאות זוז,\u0004 הרי שנת \u0003השביעית מן המנין\u0004 ואינו יכול לטעון שבשנת השמיטה לא עבד את האדמה כלל, ולכן מגיעה לו שנה אחרת. ואולם אם \u0003קבלה הימנו שבע שנים בשבע מאות זוז\u0004 — אז \u0003אין השביעית מן המנין\u0004 ויושב בה גם שנה נוספת תמורת שנת השמיטה.","ומכאן לנושא הלכתי אחר, לענין תשלום שכר פועלים: \u0003שכיר יום גובה\u0004 שכרו מבעל הבית \u0003כל הלילה\u0004 שלאחר עבודתו. \u0003שכיר לילה\u0004 — \u0003גובה\u0004 את שכרו \u0003כל היום\u0004 שלאחריו. \u0003שכיר שעות גובה כל הלילה וכל היום. שכיר שבת\u0004 \u0005[שבוע],\u0006 \u0003שכיר חדש, שכיר שנה, שכיר שבוע\u0004 (שבע שנים) — אם \u0003יצא\u0004 (סיים עבודתו) \u0003ביום\u0004 — \u0003גובה כל היום,\u0004 אם \u0003יצא בלילה גובה כל הלילה וכל היום\u0004 שלאחריו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לשכיר יום שגובה\u0004 את שכרו \u0003כל הלילה\u0004 שלאחריו? — \u0003תלמוד לומר: \"לא תלין פעלת שכיר אתך עד בקר\"\u0004 (ויקרא יט, יג), משמע שעד הבוקר משלם לו שכרו, ועד אז אין זו הלנת שכר. \u0003ומנין לשכיר לילה שגובה כל היום\u0004 — \u0003שנאמר: \"ביומו תתן שכרו\"\u0004 (דברים כד, טו).","ושואלים: \u0003אימא איפכא\u0004 \u0005[ואמור להיפך]\u0006 ששכיר לילה מקבל כל הלילה, ושכיר יום מקבל כל היום! ומשיבים: \u0003שכירות אינה משתלמת אלא בסוף\u0004 ולכן תחילת זמן תשלום השכירות הוא רק לאחר שגמר השכיר את העבודה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ממשמע שנאמר: \"לא תלין פעלת שכיר אתך\" איני יודע ש\u0004הכוונה היא \u0003\"עד בקר\"?\u0004 והלא זו המשמעות הפשוטה של \"תלין\"! אם כן \u0003מה תלמוד לומר \"עד בקר\"\u0004 — \u0003מלמד שאינו עובר אלא עד בקר ראשון בלבד\u0004 ב\"לא תלין\" ואינו עובר על כך לאחר מכן.","ושואלים: \u0003מכאן ואי\u0004 \u0003לך מאי\u0004 \u0005[מה דינו]?\u0006 \u0003אמר רב: עובר משום \"בל תשהא\".\u0004 כלומר, אף שאינו עובר עוד משום \"בל תלין\" יש עבירה בהשהיית השכר. \u0003אמר רב יוסף: מאי קראה\u0004 \u0005[מהו הכתוב]\u0006 שממנו מקור לעבירה נוספת בהשהיית התשלום — שנאמר: \u0003\"אל תאמר לרעך לך ושוב ומחר אתן ויש אתך\"\u0004 (משלי ג, כח).","\u0003תנו רבנן\u0004 \u0005[שנו\u0006 \u0003חכמים]:\u0004 \u0003האומר לחבירו צא שכור לי פועלים\u0004 — \u0003שניהם אין עוברין משום \"בל תלין\"\u0004 אם לא שילמו מיד. \u0003זה,\u0004 בעל הבית, \u0003לפי שלא\u0004 הוא עצמו \u0003שכרן,\u0004 ואין הם שכיריו במלוא משמעות המלה,"],["\u0003וזה,\u0004 השוכר, \u0003לפי שאין פעולתו\u0004 \u0005[עבודתו]\u0006 \u0003אצלו.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה?]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר להו\u0004 \u0005[להם\u0006 השוכר\u0005]\u0006 \u0003שכרכם עלי\u0004 — הרי \u0003שכרו עליו הוא\u0004 שכל האחריות על השוכר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוכר את הפועל לעשות בשלו והראהו\u0004 לעבוד \u0003בשל חבירו\u0004 — \u0003נותן לו\u0004 השוכר \u0003שכרו משלם,\u0004 ואחר כך \u0003חוזר ונוטל מבעל הבית מה שההנה אותו!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 ולא נאמרה ההלכה שאמרנו אלא לאופן ש\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שכרכם על בעל הבית,\u0004 שאז מתחלקים הם במדת מה באחריות.","ואכן מסופר: \u0003יהודה בר מרימר אמר ליה לשמעיה\u0004 \u0005[היה אומר לו לשמשו]\u0006 \u0003זיל אגיר\u0004 \u0005[לך שכור]\u0006 \u0003לי פועלים, ואימא להו\u0004 \u0005[ואמור להם]:\u0006 \u0003שכרכם על בעל הבית,\u0004 כדי שלא תעבור ב\"בל תלין\". \u0003מרימר ומר זוטרא אגרי להדדי\u0004 \u0005[היו שוכרים זה לזה פועלים]\u0006 מטעם זה.","\u0003אמר רבה בר רב הונא: הני שוקאי\u0004 \u0005[אותם אנשי\u0006 \u0003השוק]\u0004 של \u0003סורא לא עברי\u0004 \u0005[אינם עוברים]\u0006 \u0003משום \"בל תלין\"\u0004 כשאינם משלמים מיד לשכיריהם, כי \u0003מידע ידעי\u0004 \u0005[יודעים\u0006 הכל\u0005]\u0006 ש\u0003על יומא דשוקא סמיכי\u0004 \u0005[יום השוק\u0006 הם \u0005סומכים],\u0006 שאז הם מרוויחים, ויש בידם כסף, והפועל שנשכר להם יודע שלא יוכל לקבל שכרו בו ביום, \u0003אבל משום \"בל תשהא\" ודאי עובר\u0004 אם משהה את התשלום לאחר יום השוק.","שנינו במשנה ש\u0003שכיר שעות גובה\u0004 שכרו \u0003כל הלילה וכל היום\u0004 שלאחריו. \u0003אמר רב: שכיר שעות\u0004 שעבד \u0003ב\u0004\u0003יום\u0004 — \u0003גובה\u0004 שכרו \u0003כל\u0004 אותו \u0003היום, שכיר שעות\u0004 שעבד ב\u0003לילה\u0004 — \u0003גובה כל\u0004 אותו \u0003הלילה. ושמואל אמר: שכיר שעות\u0004 של \u0003יום\u0004 — אכן \u0003גובה כל היום, ושכיר שעות\u0004 של \u0003לילה\u0004 — \u0003גובה כל הלילה וכל היום.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שכיר שעות גובה כל הלילה וכל היום,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0003היה\u0004 \u0005לומר]\u0006 \u0003לך רב:\u0004 \u0003לצדדין קתני\u0004 \u0005[שנה].\u0006 כלומר, אין לקרוא דבר זה כהלכה אחת, אלא כשתי הלכות צמודות: \u0003שכיר שעות\u0004 של \u0003יום\u0004 — \u0003גובה כל היום, שכיר שעות\u0004 של \u0003לילה\u0004 — \u0003גובה כל הלילה.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 עוד: \u0003היה שכיר שבת\u0004 \u0005[שבוע],\u0006 \u0003שכיר חדש, שכיר שנה, שכיר שבוע\u0004 (שבע \u0003שנים),\u0004 אם \u0003יוצא ביום\u0004 — \u0003גובה כל היום,\u0004 ואם \u0003יוצא בלילה\u0004 — \u0003גובה כל הלילה וכל היום.\u0004 משמע שהיוצא בלילה היה גובה גם כל היום!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0003היה\u0004 \u0005לומר]\u0006 \u0003לך רב\u0004 כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 היא בנושא זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שכיר שעות\u0004 של \u0003יום\u0004 — \u0003גובה כל יום, שכיר שעות\u0004 של \u0003לילה\u0004 — \u0003גובה כל הלילה,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003ר' שמעון אומר: שכיר שעות\u0004 של \u0003יום\u0004 — \u0003גובה כל היום, שכיר שעות\u0004 של \u0003לילה\u0004 — \u0003גובה כל הלילה וכל היום.\u0004","וממשיכה ברייתא זו: \u0003מכאן אמרו\u0004 חכמים: \u0003כל הכובש שכר שכיר\u0004 ואינו משלם לו \u0003עובר בחמשה שמות\u0004 (איסורים) \u0003הללו,\u0004 שיש בהם לא תעשה, \u0003ו\u0004גם עובר על מצות \u0003עשה.\u0004 כיצד? עובר \u0003משום \"בל תעשק את רעך\"\u0004 (ראה ויקרא יט, יג), \u0003ומשום \"בל תגזל\"\u0004 (ראה שם), \u0003ומשום \"בל תעשק שכיר עני\"\u0004 (ראה דברים כד, יד), \u0003ומשום \"בל תלין\"\u0004 (ראה ויקרא יט, יג), \u0003ומשום\u0004 מצות עשה של \u0003\"ביומו תתן שכרו\"\u0004 (דברים כד, טו), \u0003ומשום\u0004 לא תעשה של \u0003\"\u0004ו\u0003לא תבוא עליו השמש\"\u0004 (שם).","ומקשים: הלא אין חמישה איסורים אלה חלים כאחד, כי \u0003הני דאיכא ביממא\u0004 \u0005[אלה שישנם ביום]\u0006 — \u0003ליכא בליליא\u0004 \u0005[אינם בלילה],\u0006 ואלה \u0003דאיכא בליליא\u0004 \u0005[שישנם\u0006 בלילה] — \u0003ליכא ביממא\u0004 \u0005[אינם ביום]\u0006 ואיך יכול לעבור על כולם? \u0003אמר רב חסדא: שם שכירות בעלמא\u0004 \u0005[המושג\u0006 \"הכובש שכר שכיר\" \u0005בכלל]\u0006 יש בו כל האיסורים האלה, ומצות עשה אחת.","מאחר ששנינו שהכובש שכר שכיר עובר בין השאר על \"לא תגזול\" ועל \"בל תעשוק\", מבררים: \u0003איזה הוא \"עושק\" ואיזהו \"גזל\",\u0004 ומה ההבדל ביניהם? \u0003אמר רב חסדא:\u0004 אם אמר לו: \u0003\"לך ושוב\", \"לך ושוב\",\u0004 ועדיין אומר שיתן — \u0003זה הוא עושק,\u0004 אם אמר: \u0003\"יש לך בידי ואיני נותן לך\"\u0004 — \u0003זה הוא גזל.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת\u0004 ממה ששנינו בברייתא: \u0003איזהו עושק שחייבה עליו תורה קרבן\u0004 — \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פקדון בעינן דקא כפר ליה ממונא\u0004 \u0005[צריכים אנו, שהוא כופר לו ממון]\u0006 ולא כדברי רב חסדא שהוא מודה שחייב לו! \u0003אלא אמר רב ששת,\u0004 זהו ההבדל: אמר לו \u0003\"נתתיו לך\"\u0004 — \u0003זהו עושק,\u0004 ואם אומר לו \u0003\"יש לך בידי ואיני נותן לך\"\u0004 — \u0003זה הוא גזל.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003איזה הוא גזל שחייבה עליו תורה קרבן דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פקדון בעינן\u0004 \u0005[אנחנו צריכים],\u0006 \u0003דקא כפר ליה ממונא\u0004 \u0005[שהוא כופר לו ממון]\u0006 ואינו מודה כלל בחובו! \u0003אלא אמר אביי:\u0004 אם אמר לו: \u0003\"לא שכרתיך מעולם\"\u0004 — \u0003זה הוא עושק,\u0004 אם אמר לו: \u0003\"נתתיו לך\"\u0004 — \u0003זה הוא גזל.\u0004","ושואלים: \u0003ולרב ששת, מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003עושק דקשיא ליה\u0004 \u0005[שקשה לו]\u0006 והקשה על דברי רב חסדא וניסה ליישב, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003גזל דלא קשיא ליה\u0004 \u0005[שאינו קשה לו]\u0006 אף שלכאורה קושיית אביי היתה מעין הקושיא שלו! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003גזל\u0004 כוונתו \u0003דגזליה והדר כפריה\u0004 \u0005[ש\u0006קודם \u0005גזל ממנו ואחר כך כפר בו].\u0006 ואין הכרח לפרש כדברי אביי דווקא.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו עושק נמי דהדר כפריה\u0004 \u0005[גם כן\u0006 אפשר לומר \u0005שחזר וכפר בו]!\u0006 ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בשלמא התם כתיב\u0004 \u0005[נניח שם,\u0006 מובן כי \u0005נאמר]\u0006 שם: \u0003\"\u0004וכחש בעמיתו בפקדון או בתשומת יד \u0003או בגזל\"\u0004 (ויקרא ה, כא) וכיון שנאמר \"וכחש\" — \u0003מכלל\u0004 הדבר אתה למד \u0003דאודי ליה מעיקרא\u0004 \u0005[שהודה לו מתחילה].\u0006 \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003עושק מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"או בעושק\"?\u0004 הלא \u0003\"או עשק\" כתיב\u0004 \u0005[נאמר],\u0006 שאין זה המשך הדברים הקודמים ביחס לכחש אלא הכוונה לעבירה לעצמה — \u0003שעשקו כבר.\u0004","ו\u0003רבא אמר:\u0004 אין צורך ליצור חלוקה מלאכותית, אלא \u0003זה הוא עושק זהו גזל,\u0004 ולהלכה אין הבדל ביניהם. \u0003ולמה חלקן הכתוב\u0004 לשני נושאים — \u0003לעבור עליו בשני לאוין,\u0004 שאם גזל — עובר גם משום גזל וגם משום עושק.","\u0003אחד שכר אדם\u0004 שעובד אצלו \u0003ואחד שכר בהמה\u0004 שמשכיר לו, \u0003ואחד שכר כלים\u0004 שמשכיר לו — \u0003יש בו משום \"ביומו תתן שכרו\"\u0004 (דברים כד, טו), \u0003ויש בו משום \"לא תלין פעלת שכיר אתך עד בקר\"\u0004 (ויקרא יט, יג). \u0003אימתי\u0004 עובר על איסורים אלה — \u0003בזמן שתבעו\u0004 השכיר. ואולם אם \u0003לא תבעו\u0004 — \u0003אינו עובר עליו. המחהו,\u0004 כלומר, נתן הוראה לאחר לשלם לו עבור עבודתו וכגון \u0003אצל חנוני,\u0004 שהיה הפועל רוצה לקנות פירות ואמר בעל הבית לחנווני שיתן לו פירות בסכום מסויים והפרעון עליו, \u0003או\u0004 שהמחהו \u0003אצל שולחני\u0004 — \u0003אינו עובר עליו,\u0004 אם אין החנווני או השולחני משלם לו.","ועוד הלכה בדינים אלה: \u0003שכיר בזמנו,\u0004 בזמן שבו תובע ואסור להלינו, אם בעל הבית טוען ששילם לו — \u0003נשבע\u0004 השכיר שלא קיבל את שכרו \u0003ונוטל\u0004 מבעל הבית. אבל אם כבר \u0003עבר זמנו\u0004 — \u0003אינו נשבע ונוטל.\u0004 אבל \u0003אם יש עדים שתבעו בזמנו\u0004 ולא פרע לו אז — \u0003הרי זה נשבע ונוטל.\u0004","שכיר \u0003גר תושב יש בו משום\u0004 מצוות עשה של \u0003\"ביומו תתן שכרו\",\u0004 אבל \u0003אין בו משום\u0004 מצוות לא תעשה של \u0003\"לא תלין פעלת שכיר אתך עד בקר\".\u0004","שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003לא\u0004 כדעת \u0003תנא קמא\u0004 \u0005[הראשון]\u0006 הדורש בברייתא מ\u0003\"מאחיך\",\u0004 \u0003ולא\u0004 כשיטת \u0003ר' יוסי בר' יהודה.\u0004 על השאלה הזו שואלים שאלת הבהרה: \u0003מאי היא\u0004 \u0005[מה זו],\u0006 כלומר, הגמרא מתייחסת למקור מסויים, ואומרת שמשנתנו איננה מתאימה לו, ואולם מהו מקור זה? ומסבירים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006"],["נאמר: \"לא תעשוק שכיר עני ואביון מאחיך או מגרך אשר בארצך בשעריך\" (דברים כד, יד), וכך למדים: \u0003\"מאחיך\"\u0004 — \u0003פרט לאחרים,\u0004 לגויים, שאינם אחים. \u0003\"\u0004מ\u0003גרך\"\u0004 — \u0003זה גר צדק, \"בשעריך\"\u0004 — \u0003זה\u0004 גר \u0003אוכל נבילות\u0004 (הקרוי בדרך כלל גר תושב, וחי בארץ ישראל, ולא קיבל עליו לקיים מצוות התורה).","\u0003אין לי\u0004 שאסור להלין \u0003אלא שכר אדם, מנין לרבות\u0004 אף שכר \u0003בהמה וכלים\u0004 שגם אותו אסור להלין — \u0003תלמוד לומר: \"בארצך\"\u0004 — \u0003כל שבארצך. וכולן,\u0004 בכל דבר שעושקים שכר שכיר \u0003עוברים בכל השמות הללו\u0004 (סוגי האיסורים) שנאמרו בענין זה.","\u0003מכאן אמרו: אחד שכר אדם ואחד שכר בהמה ואחד שכר כלים\u0004 — \u0003יש בו משום\u0004 חובה של \u0003\"ביומו תתן שכרו\"\u0004 (שם טו) \u0003ויש בהן משום \"בל תלין פעלת שכיר\"\u0004 (ראה ויקרא יט, יג). ואילו \u0003ר' יוסי בר' יהודה אומר: גר תושב יש בו משום\u0004 חובת \u0003\"ביומו תתן שכרו\"\u0004 אבל \u0003אין בו משום\u0004 איסור \u0003\"לא תלין\".\u0004 ואילו שכר \u0003בהמה וכלים אין בהן\u0004 לא זה ולא זה, \u0003אלא משום \"בל תעשוק\"\u0004 (ראה שם) \u0003בלבד.\u0004","ואם כן משנתנו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שדורש \u0003\"מאחיך\",\u0004 אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003גר תושב,\u0004 שהרי הוא משווה גר תושב לישראל לכל דבר, ולא כמשנתנו. \u0003אי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' יוסי\u0004 בר' יהודה — \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003בהמה וכלים,\u0004 שהרי לדעת ר' יוסי בהמה וכלים אין עובר עליהם!","\u0003אמר רבא: האי תנא\u0004 \u0005[תנא זה]\u0006 שבמשנתנו — \u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 \u0003הוא,\u0004 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: אחד שכר אדם, ואחד שכר בהמה ואחד שכר כלים\u0004 — \u0003יש בו משום \"ביומו תתן שכרו\" ומשום \"לא תלין\". גר תושב יש בו משום \"ביומו תתן שכרו\", ואין בו משום \"בל תלין\".\u0004 עד כאן עסקנו במציאת מקור שיטת המשנה, ומעתה באים לבירורן של השיטות השונות.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שדורש \u0003\"מאחיך\"\u0004 — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"שכיר\"\u0004 (\"לא תלין פעולת שכיר\"), \u0003\"שכיר\"\u0004 (\"לא תעשוק שכיר עני\"), שכשם שבפסוק \"לא תעשוק\" מדובר בכולם, בין בישראל בין בגר, בין באדם בין בכלים — אף ב\"בל תלין\" מדובר בכולם. \u0003ור' יוסי בר' יהודה לא גמר\u0004 \u0005[אינו לומד]\u0006 גזירה שווה זו של \"שכיר\" \"שכיר\". ומקשים: \u0003נהי\u0004 \u0005[\u0006ו\u0005אם אמנם]\u0006","\u0003לא גמר\u0004 \u0005[למד]\u0006 גזירה שווה זו של \"\u0003שכיר\u0004\" \"\u0003שכיר\u0004\", ואולם בכל מקום \u0003בהמה וכלים משום \"ביומו תתן שכרו\" נמי ניחייב\u0004 \u0005[גם כן מתחייב],\u0006 ומה המקור לדעתו שאף זה אינו בכלל? \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חנניא\u0004 בברייתא: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004ביומו תתן שכרו \u0003ולא תבא עליו השמש כי עני הוא\"\u0004 (דברים כד, א) לומר: בכתוב זה מדובר בבני אדם — \u0003מי שהן באים לידי עניות ועשירות, יצאו בהמה וכלים שאינן באין לידי עניות ועשירות.\u0004","ושואלים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאינו מתייחס לכך, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"כי עני הוא\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו]?\u0006 ומפרש: הפסוק \u0003ההוא מיבעי\u0004 \u0005[נצרך]\u0006 לו לענין אחר: \u0003להקדים עני לעשיר,\u0004 שאם אין בידו כדי לשלם לכל שכיריו ישלם לעני תחילה. \u0003ויוסי בר' יהודה\u0004 אומר: כי \u0003ההוא\u0004 דין זה \u0003מ\"לא תעשק שכיר עני ואביון\"\u0004 (שם יד) \u0003נפקא\u0004 \u0005[יוצא]\u0006 נלמד.","ושואלים: אם כן, \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 לשם מה זקוק הוא לעוד פסוק? ומשיבים: לדעתו \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 בא \u0003להקדים עני לעשיר,\u0004 \u0003וחד\u0004 \u0005[ואחד]\u0006 הפסוק השני בא \u0003להקדים עני לאביון\u0004 (עני גמור שאין בידו מאומה).","ואומרים: \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 שייאמרו שניהם, ומדוע — \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 שעני קודם ל\u0003אביון\u0004 בלבד הייתי אומר שהדין כך \u0003משום דלא כסיף למתבעיה\u0004 \u0005[ש\u0006אביון \u0005איננו מתבייש לתובעו],\u0006 שהרי הוא דל כל כך שאינו מתבייש לתבוע כסף. \u0003אבל עשיר דכסיף למתבעיה אימא\u0004 \u0005[שמתבייש לתבוע אותו\u0006 אולי \u0005נאמר]\u0006 ש\u0003לא\u0004 ושמא יש להקדים אותו. ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 רק שיש להקדים את ה\u0003עשיר\u0004 לעני — הייתי אומר שהדין כן \u0003משום\u0004 שהוא בדרך כלל \u0003לא צריך\u0004 את הכסף מיידית, ולכן אין אולי חובה ליתן לו דווקא ביומו, \u0003אבל אביון\u0004 שהוא \u0003צריך ליה\u0004 \u0005[לו,\u0006 לכסף\u0005]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר בשניהם.","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 של משנתנו: \u0003מה נפשך,\u0004 מה גישתו לענין זה? שהרי \u0003אי יליף\u0004 \u0005[אם לומד]\u0006 הוא גזירה שווה זו של \u0003\"שכיר\" \"שכיר\"\u0004 — אם כן \u0003אפילו גר תושב נמי\u0004 \u0005[גם כן]\u0006 יהיה בכלל החיוב, \u0003אי לא יליף\u0004 \u0005[אם איננו לומד]\u0006 גזירה שווה זו של \u0003\"שכיר\" \"שכיר\"\u0004 — אם כן הדין ב\u0003בהמה וכלים מנא ליה\u0004 \u0005[מנין לו]?\u0006","ומשיבים: \u0003לעולם\u0004 תפרש שהוא \u0003לא יליף\u0004 \u0005[לומד]\u0006 גזירה שווה זו של \u0003\"שכיר\" \"שכיר\" , ושאני התם\u0004 \u0005[ושונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא תלין פעלת שכיר אתך עד בקר\",\u0004 לומר: \u0003כל שפעולתו\u0004 (עבודתו) \u0003אתך,\u0004 ובכלל זה גם בהמה וכלים. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו גר תושב נמי\u0004 \u0005[גם כן]\u0006 הרי גם הוא פעל אתך! ומשיבים: מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"רעך\"\u0004 הרי זה למעט, ולומר שהדין כן רק \u0003לגבי\u0004 \u0003רעך\u0004 שמישראל \u0003ולא\u0004 לגבי \u0003גר תושב\u0004 שאיננו בכלל \"רעך\".","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו בהמה וכלים נמי\u0004 \u0005[גם כן]\u0006 אינם בכלל \"רעך\"! ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אתך\",\u0004 ומשמע — כל מי שעבד אתך. ומקשים: \u0003מה ראית לרבות בהמה וכלים ולהוציא גר תושב?\u0004 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003בהמה וכלים הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003לרבות,\u0004 ומדוע? — \u0003שכן ישנן\u0004 לפחות \u0003בכלל ממון רעך,\u0004 ואילו \u0003גר תושב אינו בכלל ממון רעך.\u0004","ושואלים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 בברייתא שדורש \u0003\"מאחיך\", האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"רעך\" מאי עביד ליה\u0004 \u0005[מה עושה הוא לו]?\u0006 ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[זה נצרך לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"רעך\"\u0004 — \u0003ולא גוי.\u0004 ותוהים: לשם מה יש צורך בלימוד זה? הרי \u0003גוי מ\"אחיך\" נפקא\u0004 \u0005[יוצא]\u0006 ואין צורך בלימוד מיוחד!","ומשיבים: \u0003חד למשרא עושקו\u0004 \u0005[חד להתיר\u0006 את העושק \u0005שעושק אותו],\u0006 \u0003וחד למשרא גזלו\u0004 \u0005[ואחד להתיר לגזול אותו].\u0006 \u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני אלה; \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 \u0003גזלו\u0004 בלבד, הייתי אומר: \u0003משום\u0004 ש\u0003לא טרח ביה\u0004 \u0005[בו\u0006 הגוי בעבודה זו\u0005],\u0006 \u0003אבל עושקו,\u0004 שאותו גוי כבר \u0003טרח ביה\u0004 \u0005[בו,\u0006 אצלו\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שמא אסור לו לעשוק אותו. ולהיפך, \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 ב\u0003עושקו\u0004 שמותר — \u0003משום\u0004 שעדיין \u0003לא אתא לידיה\u0004 \u0005[הגיע\u0006 כסף \u0005לידו],\u0006 \u0003אבל גזלו\u0004 שהוא לוקח כסף \u0003דאתא לידיה\u0004 \u0005[ש\u0006כבר \u0005בא לידו]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 שתאמר בשני המקרים.","ושואלים: \u0003ור' יוסי בר' יהודה, האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"לא תלין פעלת שכיר אתך עד בקר\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעיא ליה\u0004 \u0005[נצרך לו]\u0006 לכפי שאמר \u0003רב אסי.\u0004 ש\u0003אמר רב אסי: אפילו לא שכרו\u0004 את הפועל \u0003אלא לבצור לו אשכול אחד של ענבים,\u0004 אם מעכב את שכרו — \u0003עובר משום \"בל תלין\".\u0004","ושואלים: \u0003ואידך\u0004 \u0005[\u0006והחכם \u0005האחר],\u0006 מניין יודע הוא הלכה זו? ומשיבים: \u0003מ\u0004מה שנאמר — \u0003\"ואליו הוא נשא את נפשו\"\u0004 (דברים כד, טו) \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר, שהוא למד מכאן שמתחייב ב\"בל תלין\" על כל עבודה, שהיא \u0003דבר המוסר נפשו עליו,\u0004 שהרי הפועל משעבד עצמו לעבודה זו."],["ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 מה לומד הוא מכתוב זה? ומשיבים: הכתוב \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"ואליו הוא נשא את נפשו\"\u0004 להסביר מדוע חייבים לדקדק כל כך בדבר; \u0003מפני מה עלה זה\u0004 הפועל \u0003בכבש\u0004 גבוה \u0003ונתלה באילן ומסר את עצמו למיתה\u0004 — וכי \u0003לא על שכרו?\u0004 וכיצד יכול המעביד שלא לשלם?","\u0003דבר אחר: \"ואליו הוא נשא את נפשו\",\u0004 ללמד ש\u0003כל הכובש שכר שכיר\u0004 — \u0003כאילו נוטל נפשו ממנו.\u0004 בפירוש הדבר זה נחלקו \u0003רב הונא ורב חסדא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהכוונה היא שהוא נוטל \u0003נפשו של גזלן,\u0004 שהגוזל מן השכיר גורם שמשמים יטלו את נפשו שלו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהכוונה נוטל הוא את \u0003נפשו של\u0004 ה\u0003נגזל.\u0004","ומביאים ראיות לדבריהם: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שגוזל את \u0003נפשו של גזלן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל תגזל דל כי דל הוא ואל תדכא עני בשער\"\u0004 (משלי כב, כב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחריו \u0003\"כי ה' יריב ריבם וקבע את קבעיהם נפש\"\u0004 (שם כג), לומר שהגוזל את הדל — ה' לוקח ממנו את נפשו. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 שהכוונה \u0003נפשו של נגזל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כן ארחות כל בצע בצע את נפש בעליו יקח\"\u0004 (שם א, יט), שהגזלן אינו נוטל רק ממון, אלא בגזילת הדל — הריהו כנוטל את נפשו.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן],\u0006 \u0003הכתיב\u0004 \u0005[הלא נאמר]\u0006 \u0003\"את נפש בעליו יקח\"!\u0004 ומסבירים: הכוונה היא \u0003בעליו דהשתא\u0004 \u0005[של עכשיו],\u0006 כלומר, את נפשו של הגזלן, שלקה ממון ועכשיו הוא בעליו. ושואלים: \u0003ואידך נמי, הכתיב\u0004 \u0005[והאחר גם כן, הלא נאמר]\u0006 \u0003\"וקבע את קבעיהם נפש\"!\u0004 ומשיבים: פסוק זה יש להבינו כהסבר: \u0003מה טעם קאמר\u0004 \u0005[אמר];\u0006 \u0003מה טעם \"וקבע את קבעיהם\"\u0004 — \u0003משום דנטלו נפש,\u0004 ולכן יתבע זאת ה' ממנו.","שנינו במשנה: \u0003אימתי\u0004 נתחייב המעביד אם מלין הוא את שכר השכיר — \u0003בזמן שתבעו\u0004 השכיר, ואולם אם \u0003לא תבעו\u0004 — \u0003אינו עובר עליו.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 ממה שנאמר \u0003\"לא תלין פעלת שכיר\" יכול\u0004 יהא חייב בכך \u0003אפילו\u0004 אם \u0003לא תבעו\u0004 השכיר — \u0003תלמוד לומר: \"אתך\",\u0004 כוונתו: \u0003לדעתך,\u0004 שאתה יודע שלא שילמת לו.","\u0003יכול אפילו אין לו\u0004 לבעל הבית מה לשלם יתחייב עליו — \u0003תלמוד לומר: \"אתך\",\u0004 הכוונה היא: \u0003שיש אתך.\u0004 \u0003יכול אפילו המחהו\u0004 בעל הבית \u0003אצל חנוני,\u0004 שהיה הפועל רוצה לקנות פירות ואמר בעל הבית לחנווני שיתן לו פירות בסכום מסויים והפרעון עליו, \u0003או\u0004 שהמחהו \u0003אצל שולחני\u0004 יעבור משום \"בל תלין\" — \u0003תלמוד לומר \"אתך\"\u0004 שהחוב מוטל עליו \u0003ולא שהמחהו אצל חנוני ואצל שולחני\u0004 שעכשיו ההיוב איננו עוד עליו.","עוד שנינו במשנה שאם \u0003המחהו אצל חנוני,\u0004 או \u0003אצל שולחני\u0004 — \u0003אינו עובר. איבעיא להו\u0004 \u0005[נשאלה להם ללומדים]\u0006 שאלה זו: אם החנווני או השולחני לא שילם משום מה, האם השכיר \u0003חוזר\u0004 אל בעל הבית בתביעה \u0003או אינו חוזר,\u0004 שמעתה אין לו טענות אלא אל המתווך (השולחני, החנווני) בלבד? \u0003רב ששת אמר: אינו חוזר, ורבה אמר: חוזר.\u0004","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את שיטתי זו — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 \u0003אינו עובר עליו,\u0004 ומכאן אני מדקדק בלשון: \u0003מעבר הוא דלא עבר\u0004 \u0005[לעבור הוא שאינו עובר]\u0006 עוד על מצות לא תעשה, \u0003הא מיהדר\u0004 \u0005[אבל לחזור]\u0006 — \u0003הדר\u0004 \u0005[חוזר]\u0006 השכיר אליו בתביעתו. \u0003ורב ששת אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ש\u0003אינו עובר\u0004 — כוונתו: \u0003אינו בתורת לעבור,\u0004 שעל ידי ההמחאה יצא לגמרי מגדר חיוב זה.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 את \u0003רב ששת\u0004: פועל העובד בדרך \u0003קבלנות,\u0004 שאינו מקבל שכר עבור שעות עבודה אלא קיבל על עצמו לגמור עבודה מסויימת תמורת שכר מוגדר מראש, האם כאשר המעביד מעכב את שכרו בתום העבודה הוא \u0003עובר עליו משום \"בל תלין\", או אין עובר\u0004 עליו \u0003משום \"בל תלין\"?\u0004","ומבחינה משפטית עקרונית השאלה היא זו: האם \u0003אומן קונה בשבח כלי,\u0004 כלומר, האם אומן העושה מלאכה ומתקן (או יוצר כלי) יש לו זכות קנין בכלי מתוך שהוא משביח אותו במלאכתו, \u0003ו\u0004משום כך, התשלום שהוא צריך לקבל עבור הכלי \u0003הלואה היא,\u0004 ובהלוואה אין חובה לשלם מיד. \u0003או אין אומן קונה בשבח כלי,\u0004 ואין לאומן אלא התחייבות בעל הכלי לשלם לו, \u0003ו\u0004אם כן \u0003שכירות היא?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: עובר\u0004 עליו. הקשו עליו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבקבלנות \u0003אינו עובר!\u0004 והשיב: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003שהמחהו אצל חנוני ואצל שולחני.\u0004","ומציעים: \u0003נימא מסייעא ליה\u0004 \u0005[האם נאמר שמסייעת לו]\u0006 הברייתא הבאה: \u0003הנותן טליתו לאומן\u0004 שיעשה בה תיקון, \u0003גמרה\u0004 האומן \u0003והודיעו\u0004 לבעל הטלית, \u0003אפילו מכאן ועד עשרה ימים\u0004 לאחר גמר המלאכה אם לא שילם לו בעל הטלית תמורת העבודה \u0003אינו עובר משום \"בל תלין\".\u0004 ואם \u0003נתנה לו\u0004 האומן אפילו \u0003בחצי היום, מששקעה עליו חמה\u0004 מיד \u0003עובר משום \"בל תלין\".\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אומן קונה בשבח כלי\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003עובר?\u0004 אלא ודאי כדברי רב ששת.","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 מכאן אין להוכיח, שכו אפשר לפרש ששם מדובר \u0003בגרדא דסרבלא\u0004 \u0005[בריכוך גלימה עבה]\u0006 שאין במלאכה זו שבח. ושואלים: \u0003למאי יהבה ניהליה\u0004 \u0005[למה נתן אותה לו\u0006 לאומן\u0005]\u0006 — \u0003לרכוכי\u0004 \u0005[לרכך\u0006 אותה\u0005],\u0006 ואולם ריכוך זה \u0003היינו שבחיה\u0004 \u0005[הרי זהו שבחו]\u0006 ומשיבים:","\u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא בשכיר (שאינו קבלן המקבל חפץ לגמרו) \u0003דקא אגריה מיניה לבטושי בטשא ובטשא במעתא\u0004 \u0005[ששכר אותו להכות בגלימה, מכה מכה במעה].\u0006 ואם כן, הרי זו שכירות רגילה, ולא קבלנות, ובכגון זה ודאי יש איסור הלנת שכר."],["שנינו במשנה כי \u0003שכיר בזמנו נשבע ונוטל.\u0004 ושואלים: \u0003שכיר אמאי תקינו ליה רבנן למשתבע ושקיל\u0004 \u0005[מדוע תיקנו לו חכמים שישבע ויקח]\u0006 בניגוד לנוהג הכללי שהנתבע הוא שנשבע שאינו חייב ונפטר מן התביעה?","\u0003אמר רב יהודה אמר שמואל: הלכות גדולות שנו כאן.\u0004 ומיד תוהים על הלשון: וכי \u0003הני הלכתא נינהו\u0004 \u0005[אלה הלכות הן]?\u0006 הלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003תקנות נינהו\u0004 \u0005[הן]\u0006 להסדיר את ענייני המשא והמתן, ולא הלכות שהכל חייבים לעשותן תמיד. \u0003אלא\u0004 יש לתקן את הלשון כך, \u0003אמר רב יהודה אמר שמואל: תקנות גדולות שנו כאן.\u0004 ושוב תוהים על הלשון: \u0003גדולות\u0004 — \u0003מכלל\u0004 הלשון אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 תקנות \u0003קטנות,\u0004 ומה הן אותן תקנות קטנות?","\u0003אלא אמר רב נחמן אמר שמואל: תקנות קבועות שנו כאן\u0004 שיש בהן צורך במציאות החיים. וכך יש להבין: בעצם חיוב ה\u0003שבועה\u0004 של \u0003בעל הבית היא\u0004 שהוא הנתבע, והיה צריך להשבע ולהפטר. \u0003ו\u0004אולם \u0003עקרוה רבנן\u0004 \u0005[חכמים]\u0006 את ה\u0003שבועה\u0004 מ\u0003בעל הבית ושדיוה\u0004 \u0005[והטילוה]\u0006 על ה\u0003שכיר\u0004 \u0003משום כדי חייו\u0004 של ה\u0003שכיר\u0004 שהרי השכיר נזקק לשכר זה כדי חייו, ואם ישבע בעל הבית ויפטר ימצא השכיר ללא כסף. ותוהים \u0003ומשום כדי חייו\u0004 של ה\u0003שכיר מפסדנא ליה\u0004 \u0005[מפסידים אנו לו]\u0006 \u0003לבעל הבית?\u0004 שהרי אם יש כאן חשש לשבועת שקר, מדוע יפסיד בעל הבית דווקא?","ומשיבים: \u0003בעל הבית גופיה ניחא ליה דמשתבע\u0004 \u0005[עצמו נוח לו שיישבע]\u0006 ה\u0003שכיר ושקיל\u0004 \u0005[ויקח]\u0006 \u0003כי היכי דליתגרו ליה\u0004 \u0005[כדי שיישכרו לו]\u0006 \u0003פועלים,\u0004 שהרי על ידי כך יודעים הם ששכרם מובטח להם. ושואלים: ומדוע לא נאמר כי ה\u0003שכיר גופיה\u0004 \u0005[עצמו]\u0006 \u0003ניחא ליה דמשתבע\u0004 \u0005[נוח לו שיישבע]\u0006 \u0003בעל הבית ויפקע, כי היכי דליגרוהו\u0004 \u0005[ויפטר, כדי שישכרו אותו]\u0006 שאם יכביד הדבר על בעל הבית — לא ישכור שכירים! ומשיבים: \u0003בעל הבית על כרחיה אגר\u0004 \u0005[על כרחו הוא שוכר].\u0006 ושואלים: \u0003שכיר נמי\u0004 \u0005[גם כן]\u0006 \u0003בעל כרחיה איתגר\u0004 \u0005[בעל כרחו נשכר]!\u0006","\u0003אלא\u0004 עלינו לחזור בנו מן ההסבר הקודם ולומר טעם אחר, \u0003בעל הבית טרוד בפועלים הוא\u0004 ויש מקום להניח שמא בתוך טרדתו שכח, וסבור ששילם. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמסתבר שבעל הבית הוא ששכח \u0003ניתב ליה\u0004 \u0005[ושיתן לו]\u0006 אם כן \u0003בלא שבועה,\u0004 שהרי יש רגלים לדבר ששכח בעל הבית! ומשיבים: שבוע זו היא \u0003כדי להפיס דעתו של בעל הבית,\u0004 שאם לא ישבע השכיר ידמה בעל הבית בנפשו שרימו אותו.","ושואלים: הלא יש דרך אחרת לצאת מקושי זה \u0003וניתב ליה\u0004 \u0005[ושיתן לו]\u0006 תמיד בעל הבית לשכיר \u0003בעדים,\u0004 ואז שוב לא יהיה מקום לטענה שלא נתן! ומשיבים: \u0003טריחא להו מילתא\u0004 \u0005[מטריח להם הדבר]\u0006 הן לבעל הבית והן לשכיר, לחפש בכל פעם עדים. ושואלים: \u0003וניתב ליה מעיקרא\u0004 \u0005[ושיתן לו מתחילה]\u0006 שבעל הבית ישלם לשכיר לפני העבודה, כשאינו טרוד כל כך? ומשיבים: \u0003שניהם רוצים בהקפה\u0004 שיהא התשלום בסוף הזמן, בעל הבית שמא אין לו עדיין ממון בידו. והשכיר מחשש שמא במשך היום יאבד את הכסף.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם זהו הטעם, \u0003אפילו קצץ נמי\u0004 \u0005[גם כן],\u0006 שאם יש ויכוח בין השכיר ובעל הבית ביחס לסכום שקבעו כתשלום — ישבע השכיר. \u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005],\u0006 אם ה\u0003אומן אומר: שתים קצצת לי\u0004 כשכר, \u0003והלה\u0004 נותן העבודה \u0003אומר:\u0004 \u0003לא קצצתי לך אלא אחת,\u0004 במקרה זה \u0003המוציא מחבירו עליו הראיה.\u0004 ומדוע אין אומרים שבעל הבית טרוד ושוכח? ומשיבים: \u0003קציצה\u0004 בקביעת שכר \u0003ודאי מידכר דכירי לה אינשי\u0004 \u0005[\u0006\u0005ודאי זוכרים אותה אנשים]\u0006 ואין לחשוש שבעל הבית שכח עד כדי כך.","ושואלים שוב: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 אם חוששים אנו שבעל הבית שכח מפני טרדתו, \u0003אפילו עבר זמנו נמי\u0004 \u0005[גם כן]\u0006 ישבע הפועל ויטול, \u0003אלמה תנן\u0004 \u0005[\u0006ו\u0005מדוע שנינו\u0006 במשנה\u0005]:\u0006 \u0003עבר זמנו\u0004 — \u0003אינו נשבע ונוטל?\u0004 ומשיבים: שם הטעם הוא משום \u0003חזקה: אין בעל הבית עובר משום \"בל תלין\".\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כי \u0003בעל הבית טרוד בפועליו הוא!\u0004 ודוחים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים — \u0003מקמיה דלימטייה\u0004 \u0005[לפני שיגיע]\u0006 \u0003זמן חיוביה\u0004 \u0005[חיובו]\u0006 לשלם, שאז יתכן שמפני הטירדה אינו זוכר אם שילם כבר,"],["\u0003אבל\u0004 אם כבר \u0003מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן חיוביה\u0004 \u0005[חיובו]\u0006 — \u0003רמי אנפשיה ומידכר\u0004 \u0005[\u0006הריהו \u0005מטיל על עצמו ונזכר]\u0006 בכל הפרטים.","ושואלים: מדוע סומכים אנו על חזקת בעל הבית? \u0003וכי שכיר\u0004 חשוד שהוא \u0003עובר משום \"בל תגזל\"?\u0004 ומשיבים: \u0003התם תרי חזקי\u0004 \u0005[שם\u0006 אצל בעל הבית \u0005שתי חזקות]\u0006 הן, \u0003הכא חדא חזקה\u0004 \u0005[כאן\u0006 בשכיר \u0005חזקה אחת]\u0006 היא. כיצד? ל\u0003גבי בעל הבית איכא תרי חזקי\u0004 \u0005[יש שתי חזקות]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 מהן ש\u0003אין בעל הבית עובר משום \"בל תלין\", וחדא\u0004 \u0005[ואחת]\u0006 ש\u0003אין שכיר משהא שכרו\u0004 בלא לתבוע. \u0003והכא\u0004 \u0005[וכאו]\u0006 יש רק \u0003חדא חזקה\u0004 \u0005[חזקה אחת]\u0006 ולא שתים.","שנינו במשנה ש\u0003אם יש עדים שתבעו\u0004 — \u0003הרי זה נשבע ונוטל\u0004 אפילו לאחר זמן. ושואלים: מה צורך יש בעדים? \u0003והא קתבעו לקמן\u0004 \u0005[והרי הוא תובע אותו לפנינו]!\u0006 \u0003אמר רב אסי:\u0004 הכוונה — עדים \u0003שתבעו בזמנו.\u0004 ושואלים: \u0003ודלמא לבתר הכי\u0004 \u0005[ושמא לאחר מכן]\u0006 \u0003פרע,\u0004 ואם כן מה ההבדל אם תבעו בזמנו? \u0003אמר אביי:\u0004 שהעדים מעידים \u0003שתבעו כל זמנו.\u0004","ושואלים: \u0003ו\u0004כי \u0003לעולם לא פרע ליה\u0004 \u0005[אינו פורע לו]?!\u0006 האם מפני שתבעו בזמנו יוכל תמיד לתבוע מבעל הבית ויהא נאמן?! \u0003אמר רב חמא בר עוקבא:\u0004 הכוונה היא ש\u0003כנגד אותו היום של תביעה\u0004 נותנים לו יום אחר שבו יכול השכיר לטעון שעדיין לא שולם לו.","\u0003המלוה את חבירו\u0004 והגיע זמן הפרעון ולא פרע — \u0003לא ימשכננו\u0004 לקחת מרכושו דבר להבטחת תשלום ההלוואה \u0003אלא בבית דין,\u0004 ואינו רשאי לקחת בעצמו. \u0003ולא יכנס לביתו ליטול משכונו, שנאמר:\u0004 \"כי תשה ברעך משאת מאומה לא תבא אל ביתו לעבוט עבוטו \u0003בחוץ תעמוד\u0004 והאיש אשר אתה נושה בו יוציא אליך את העבוט החוצה\" דברים כד, י–יא). \u0003היו לו\u0004 ללווה \u0003שני כלים\u0004 מאותו מין — \u0003נוטל אחד ומניח אחד\u0004 ברשות הלווה.","\u0003ומחזיר\u0004 המלוה \u0003את הכר בלילה\u0004 שתשמיש לילה הוא, וצריך הלווה לישון עליו, \u0003ואת המחרישה\u0004 שצריך לעבוד בה \u0003ביום\u0004 — מחזיר ביום. \u0003ו\u0004אולם \u0003אם מת\u0004 הלווה — \u0003אינו מחזיר ליורשיו. רבן שמעון בן גמליאל אומר: אף ל\u0004לווה \u0003עצמו אינו מחזיר אלא עד שלשים יום, ומשלשים יום ולהלן מוכרן בבית דין\u0004 וגובה על ידי כך את חובו.","\u0003אמר שמואל: שליח בית דין\u0004 שנתנו לו רשות לקחת כדי שיעור ההלוואה \u0003מנתח נתוחי\u0004 \u0005[לחטוף]\u0006 מן החייב כשנמצא בשוק — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל משכוני\u0004 \u0005[\u0006להכנס לביתו \u0005ולמשכן]\u0006 — \u0003לא.\u0004 ושואלים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המלוה את חבירו לא ימשכננו אלא בבית דין, מכלל\u0004 הדברים אתה למד כי \u0003בבית דין\u0004 כן \u0003ממשכנין!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך שמואל:\u0004 \u0003אימא\u0004 \u0005[אמור\u0006 ופרש\u0005]:\u0006 \u0003לא ינתחנו,\u0004 כלומר, לא יקח ממנו בכח \u0003אלא בבית דין.\u0004 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003דקתני סיפא\u0004 \u0005[ששנינו בסופה\u0006 של \u0005משנתנו]:\u0006 \u0003לא יכנס לביתו ליטול משכונו.\u0004 ונברר: \u0003מני\u0004 \u0005[במי\u0006 מדובר שם\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שב\u0003בעל חוב\u0004 מדובר — הלא כבר \u0003מרישא שמע מינה\u0004 \u0005[מתחילת\u0006 המשנה \u0005לומד אתה]\u0006 זאת, שהרי אמרנו שהמלוה אינו רשאי למשכנו! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ל\u0003שליח בית דין,\u0004 ובכל זאת נאמר שלא יכנס לביתו!","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 — \u0003לא איריא\u0004 \u0005[אינו שייך\u0006 ואינו הוכחה\u0005].\u0006 ומדוע — שאפשר לפרש כי \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003המלוה את חבירו\u0004 — \u0003לא ימשכננו אלא בבית דין, מכלל\u0004 זה נלמד ש\u0003בבית דין ממשכנים, ו\u0004אולם \u0003בעל חוב אפילו נתוחי נמי\u0004 \u0005[לחטוף\u0006 משלו \u0005גם כן]\u0006 \u0003לא,\u0004 שאין מתירין לו כלל, כדי \u0003שלא יכנס לביתו ליטול משכונו.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על שמואל ממה ששנינו בברייתא: נאמר \u0003\"לא יחבל ריחים ורכב\"\u0004 (דברים כד, ו), ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003דברים אחרים\u0004 — \u0003חבל,\u0004 רשאי אתה לחבול. וכן נאמר \u0003\"\u0004ו\u0003לא תחבל בגד אלמנה\"\u0004 (שם יז), ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003של אחרים\u0004 — \u0003תחבל,\u0004 ונברר: \u0003מאן\u0004 \u0005[מי]\u0006 יכול לעשות זאת? \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בעל\u0004 ה\u0003חוב\u0004 — \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 במקרא \u0003\"לא תבא אל ביתו לעבט עבטו\"\u0004 (שם י), \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003שליח בית דין,\u0004 ומשמע ששליח בית דין רשאי להכנס ולמשכן, אף כי אינו רשאי לקחת כל דבר!","\u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן קמיה\u0004 \u0005[בפני]\u0006 \u0003רב יוסף, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: לעולם\u0004 מדובר \u0003בבעל חוב,\u0004 והכתוב בתורה שאסור לו לקחת דברים מסויימים אין להבינו לעצמו, אלא כתוספת לאיסור הכולל להכנס לביתו של החייב, \u0003ולעבור עליו בשני לאוין.\u0004 שאם למשל לקח ריחים ורכב עובר גם משום \"לא תבוא אל ביתו\" וגם משום לאו זה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מה ששנינו בברייתא אחרת: \u0003ממשמע שנאמר \"בחוץ תעמד\"\u0004 (שם יא) \u0003איני יודע ש\"האיש אשר אתה נשה בו יוציא\"\u0004 (שם)?! \u0003אלא מה תלמוד לומר \"והאיש\"\u0004 שהוא לשון ריבוי — הרי זה בא \u0003לרבות שליח בית דין.\u0004 ומציעים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש ש\u0003שליח בית דין\u0004 דינו \u0003כלוה,\u0004 שכשם שהלווה נכנס לביתו בכל עת, כן יכול שליח בית דין לעשות זאת."],["\u0003לא, שליח בית דין\u0004 דינו \u0003כמלוה\u0004 שחייב לעמוד בחוץ עד שיוציא אליו בעל הבית.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 שאמרו חכמים על הכתוב \u0003\"אם חבל תחבל שלמת רעך\u0004 עד בא השמש תשיבנו לו\u0003\"\u0004 (שמות כב, כה) — \u0003בשליח בית דין הכתוב מדבר. אתה אומר\u0004 ש\u0003בשליח בית דין הכתוב מדבר, או אינו\u0004 מדבר \u0003אלא בבעל חוב\u0004 (במלוה)? \u0003כשהוא אומר \"לא תבא אל ביתו לעבט עבטו\"\u0004 (דברים כד, י) — \u0003הרי בעל חוב אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 את דברי הכתוב \u0003\"אם חבל תחבל שלמת רעך\"\u0004 — \u0003בשליח בית דין הכתוב מדבר,\u0004 משמע ששליח בית דין רשאי למשכן!","ומסכמים: נושא זה \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא];\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שליח בית דין שבא למשכנו\u0004 — \u0003לא יכנס לביתו למשכנו, אלא עומד מבחוץ, והלה\u0004 החייב \u0003מוציא לו משכון, שנאמר \"בחוץ תעמוד והאיש\"\u0004 (שם יא), שמפרש שאף האיש שהוא שליח בית דין דינו כמלוה עצמו.","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בעל חוב שבא למשכנו\u0004 — \u0003לא יכנס לביתו למשכנו, אלא עומד בחוץ, והלה\u0004 החייב \u0003נכנס ומוציא לו משכונו, שנאמר: \"בחוץ תעמד\"\u0004 (שם). \u0003ושליח בית דין שבא למשכנו\u0004 — \u0003הרי זה נכנס לביתו וממשכנו.\u0004","\u0003ולא ימשכננו דברים שעושין בהן אוכל נפש\u0004 שהם נחוצים לו, שאסרה התורה במפורש לקחתם. \u0003ונותן\u0004 (כלומר, משאיר השליח) \u0003מטה ומטה ומצע\u0004 (בגדים ושמיכות המטה) — \u0003לעשיר. מטה, ומטה ומפץ\u0004 (מחצלת) — \u0003לעני.\u0004 ודבר זה משאירים \u0003לו\u0004 לחייב עצמו, \u0003אבל לא לאשתו ולא לבניו ולבנותיו,\u0004 שלא הטילה התורה חובה על המלוה לדאוג להם.","ומעירים: \u0003כדרך שמסדרין לבעל חוב,\u0004 כלומר, שמשאירים לו דברים מסויימים לשימושו ואין נוטלין ממנו הכל — \u0003כך מסדרין בערכין.\u0004 שאם נדר אדם לתת להקדש ערך מסויים (ראה ויקרא פרק כז), ואין כל הכסף בידו — מסדרין לו. על פיסקה זו תוהים: \u0003כלפי לייא\u0004 \u0005[לאן אתה הולך]?!\u0006 הלא אומר אתה היפך הסברה! שהרי \u0003עיקר\u0004 דין זה של \u0003סידור\u0004 — לחייב שאין נוטלים ממנו הכל \u0003בערכין כתיב\u0004 \u0005[\u0006הוא ש\u0005נאמר]\u0006 במקרא, וממנו למדים! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003כדרך שמסדרין בערכין\u0004 שמפורש בהם הדבר — \u0003כך מסדרין בבעל חוב.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: ו\u0003נותן מטה ומטה ומצע לעשיר, מטה ומטה ומפץ לעני.\u0004 ושואלים: \u0003למאן\u0004 \u0005[למי]\u0006 צריך מטה נוספת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לאשתו לבניו ולבנותיו\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 במפורש, \u0003אבל לא לאשתו ולבניו ולבנותיו! אלא\u0004 ודאי \u0003אידי ואידי לדידיה\u0004 \u0005[זה וזה בשבילו].\u0006","ושואלים: \u0003תרתי\u0004 \u0005[שתיים]\u0006 \u0003למה לי\u0004 (לו)? והלא די לו במטה אחת לכל צרכיו! ומשיבים: \u0003חדא דאכיל עלה וחדא דזג עלה\u0004 \u0005[אחת שאוכל עליה ואחת שישן עליה],\u0006 ו\u0003כ\u0004דברי \u0003שמואל.\u0004 ש\u0003אמר שמואל\u0004 שהיה במקצועו רופא מומחה: \u0003כל מילי ידענא אסותייהו, לבר מהני תלת\u0004 \u0005[כל הדברים\u0006 הגורמים חולי \u0005יודע אני את רפואתם, חוץ משלושה אלה]:\u0006 \u0003מאן דאכיל אהינא מרירא אליבא ריקנא\u0004 \u0005[מי שאוכל תמרה מרה על לב ריק],\u0006 כלומר, מבלי להקדים לאכול משהו, \u0003ומאן דאסר מיתנא דכיתנא רטיבא אחרציה\u0004 \u0005[ומי שחוגר חגורת פשתן רטובה על מותניו],\u0006 \u0003ומאן דאכיל נהמא\u0004 \u0005[ומי שאוכל לחם]\u0006 \u0003ו\u0004הוא \u0003לא מסגי\u0004 \u0005[הולך]\u0006 \u0003ארבעה גרמידי\u0004 \u0005[אמות]\u0006 לאחר מכן. ומשום כך משאירים לאדם שתי מיטות, אחת שיאכל עליה ואחת שיוכל לישון עליה, ושיהיה מרחק מסויים ביניהן, שלא יצטרך לאכול ולישון על גבי אותה מיטה ולא יהלך אחר האוכל.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב נחמן:\u0004 \u0003כדרך שמסדרין בערכין\u0004 — \u0003כך מסדרין בבעל חוב. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003השתא זבוני מזבנינן ליה\u0004 \u0005[הרי\u0006 עכשיו \u0005אנו מוכרים אותו,\u0006 את הערבון\u0005]\u0006 וכי \u0003סדורי מסדרינן ליה\u0004 \u0005[אנו מסדרים לו]\u0006 שישאר דבר בידו?! ושואלים: \u0003ומי מזבנינן ליה\u0004 \u0005[והאם מוכרים אותו]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 ש\u0003מחזיר\u0004 המלוה \u0003את הכר בלילה\u0004 שתשמיש לילה הוא, וצריך הלווה לישון עליו, \u0003ואת המחרישה\u0004 שצריך לעבוד בה \u0003ביום,\u0004 והרי שאין מוכרים!","ומשיבים: ה\u0003תנא,\u0004 חוזר המשניות, \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל תנא קמיה\u0004 \u0005[שנה לפניו],\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]\u0006 רב נחמן: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003ל\u0004שיטת \u0003רבן שמעון בן גמליאל זבוני מזבנינן ליה\u0004 \u0005[מוכרים אנו אותו]\u0006 וכי \u0003סדורי מסדרינן ליה\u0004 \u0005[מסדרים אנו\u0006 עוד \u0005לו]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אף לעצמו אינו מחזיר אלא עד שלשים יום, מכאן ואילך מוכרן בבית דין.\u0004","ושואלים: \u0003וממאי דכי קאמר\u0004 \u0005[ומנין\u0006 ידע אתה \u0005כאשר אמר]\u0006 \u0003רבן שמעון בן גמליאל זבוני\u0004 \u0005[למכור]\u0006 — \u0003לגמרי קאמר\u0004 \u0005[אמר]?\u0006 \u0003דלמא הכי קאמר\u0004 \u0005[שמא כך אמר]:\u0006 \u0003עד שלשים יום הדר ליה בעיניה\u0004 \u0005[מחזיר לו כמו שהוא],\u0006 \u0003מכאן ואילך מיהדר ליה למאי דחזי ליה, ומזבנינן מאי דלא חזי ליה\u0004 \u0005[מחזיר לו למה שראוי לו ומוכרים מה שאינו ראוי לו]?\u0006","ודוחים: \u0003אי סלקא דעתך אית ליה\u0004 \u0005[אם עולה על דעתך לומר\u0006 ש\u0005יש לו]\u0006 \u0003לרבן שמעון בן גמליאל,\u0004 שהוא מקבל \u0003האי סברא\u0004 \u0005[סברה זו],\u0006 אם כן \u0003ליכא מידי דלא חזי ליה\u0004 \u0005[אין דבר שאינו ראוי לו].\u0006 שכן \u0003אמר אביי: רבן שמעון בן גמליאל, ור' שמעון, ור' ישמעאל, ור' עקיבא כולהו סבירא להו\u0004 \u0005[כולם סבורים]\u0006 שיטה אחת: \u0003כל ישראל בני מלכים הן.\u0004 כלומר, אין אנו יכולים לומר שאדם מישראל אינו ראוי להשתמש בדבר מסויים, אפילו כשהוא דבר של מותרות.","ומפרטים: \u0003רבן שמעון בן גמליאל\u0004 מנין יודעים אנו את שיטתו זו — ששנינו במשנה: אין מטלטלין בשבת \u0003לא את הלוף ולא את החרדל\u0004 כאשר אינן מתוקנים עדיין למאכל אדם, לפי שאינם ראויים כעת לכל שימוש, ומוקצים הם. ו\u0003רבן שמעון בן גמליאל מתיר בלוף, מפני שהוא מאכל לעורבין,\u0004 ועשירי ישראל היו מגדלים עורבים לשם נוי ושעשוע. וכיון שמתיר את הלוף בטלטול לכל, לאו דווקא לעשירים, הרי שהוא סבור שכל ישראל ראויים לנהוג כעשירים.","ש\u0003ר' שמעון\u0004 אף דעתו כן מנין לנו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בני מלכים סכין שמן וורד על גבי מכותיהן בשבת\u0004 אף שסתם אנשים משתמשים בשמן זה לרפואה, ולהם אסור להשתמש בו לפי שאסורה רפואה בשבת, והטעם — \u0003שכן דרכן לסוך\u0004 שמן וורד אף \u0003בחול. ר' שמעון אומר: כל ישראל בני מלכים הן,\u0004 וכולן ראויים סוך בשמן וורד.","\u0003ישמעאל ור' עקיבא\u0004 מניין שהם סבורים כך — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו נושין בו אלף זוז ולבוש\u0004 אותו אדם \u0003איצטלא\u0004 \u0005[גלימה]\u0006 \u0003בת מאה מנה\u0004 (עשרת אלפים זוז) — \u0003מפשיטין אותה ממנו ומלבישים אותו איצטלא הראויה לו,\u0004 ובשאר ישלם את חובו. \u0003ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' ישמעאל, ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 \u0003משום ר' עקיבא: כל ישראל ראוין לאותה איצטלא,\u0004 ואין מוכרים בגד פרטי של אדם, לפי שכל ישראל ראויים לפאר זה.","ושואלים: \u0003ולמאי דסליק אדעתין מעיקרא, דיהיב ליה מאי דחזי ליה, ומזבנינן מאי דלא חזי ליה\u0004 \u0005[ולפי מה שעלה בדעתנו מתחילה\u0006 לומר \u0005שנותן לו\u0006 את \u0005מה שראוי לו, ומוכרים מה שאינו ראוי לו]\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003כר וכסת\u0004 מוכרים כי \u0003חזי ליה דביני ביני\u0004 \u0005[\u0006מה \u0005שראוי לו\u0006 הוא ההבדל \u0005שבין זה וזה]\u0006 שיכול שיקנה כר וכסת גרועים יותר, ואת עודף המחיר של הכר והכסת המשובחים יתן לבעל חוב. \u0003אלא מחרישה למאי חזיא\u0004 \u0005[למה\u0006 היא \u0005ראויה]\u0006 כלומר, מה יכול להיות כאן הבדל במחיר? \u0003אמר רבא בר רבה:\u0004 מדובר כאן ב\u0003מחרישה דכספא\u0004 \u0005[של כסף],\u0006 שאינה כלי עבודה אלא תכשיט.","\u0003מתקיף ליה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חגא\u0004 על כל אותה שיטה כללית של סידור לבעל חוב: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 המלוה ללווה: \u0003לאו עלי קרמית\u0004 \u0005[לא עלי אתה מוטל]\u0006 לדאוג לצרכיך, ומדוע דווקא אני, שהלוויתי לך כסף, צריך לדאוג גם שישאר לך כדי פרנסתך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004"],["\u0003איברא עליה קרמי\u0004 \u0005[אכן\u0006 באמת, \u0005עליו הוא מוטל],\u0006 \u0003משום שנאמר\u0004 באותו ענין של השבת העבוט: \u0003\"ולך תהיה צדקה\"\u0004 (דברים כד, יג), משמע שעל המלוה חלה במיוחד חובת הצדקה כלפי הלווה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו שכבר נגענו בה קודם: \u0003מהו\u0004 הדין בענין \u0003שיסדרו בבעל חוב,\u0004 האם משאירים לבעל חוב מקצת רכושו שיוכל לחיות כדרכו (ולו גם בצמצום)? ומבחינת מקור ההלכה השאלה היא: \u0003מי גמר\u0004 \u0005[האם לומד]\u0006 הוא בגזירה שווה \u0003\"מיכה\" \"מיכה\" מערכין, או לא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003שלח רבין באגרתיה\u0004 \u0005[במכתבו\u0006 מארץ ישראל\u0005]:\u0006 \u0003דבר זה שאלתי לכל רבותי, ולא אמרו לי דבר. ברם כך היתה שאלה\u0004 בנושא דומה, ששמעתי שדנו בה: \u0003האומר \"הרי עלי מנה לבדק הבית\" מהו שיסדרו\u0004 בו? שהרי במפורש נאמר הדבר רק בדיני ערכין.","ובזה \u0003ר' יעקב משמיה\u0004 \u0005[משמו]\u0006 של \u0003בר פדא, ור' ירמיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אילפא אמרי\u0004 \u0005[אומרים]:\u0006 דבר זה נלמד ב\u0003קל וחומר מבעל חוב; ומה בעל חוב שמחזירין\u0004 לו את המשכון — \u0003אין מסדרין\u0004 לו כלום לאחר שלושים יום, \u0003הקדש שאין מחזירין\u0004 לו משכון — \u0003אינו דין שאין מסדרין\u0004 לו?! \u0003ו\u0004אילו \u0003ר' יוחנן אמר: \"\u0004איש כי יפליא \u0003נדר בערכך\"\u0004 (ויקרא כז, ב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ומכאן נלמד שאין דין סידור מיוחד לערכים, אלא \u0003מה ערכין מסדרין\u0004 — \u0003אף הקדש מסדרין.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 החכמים האחרים שאינם סבורים כן, מה למדים הם מן ההשוואה הזו של נדרים וערכין? ומשיבים: \u0003ההוא\u0004 לדעתם בא הדבר ללמד הלכה אחרת, \u0003ל\u0004ענין \u0003נידון בכבודו הוא דאתא.\u0004 כלומר, שאדם המעריך חלק נכבד ועיקרי מגופו, אין אנו אומרים שדי לו שיתן רק דמי חלק זה, אלא יתן דמי כל גופו. ומן הכתוב \"נדר בערכך\" למדים: \u0003מה ערכין נידון בכבודו\u0004 — \u0003אף הקדש נידון בכבודו.\u0004","ושואלים: \u0003ויסדרו בבעל חוב\u0004 לפי \u0003קל וחומר מערכין; ומה ערכין שאין מחזירין\u0004 משכון — \u0003מסדרין\u0004 לו, \u0003בעל חוב שמחזירין\u0004 לו משכון — \u0003אינו דין שמסדרין?\u0004 ודוחים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם מך הוא מערכך\u0004 והעמידו לפני הכהן והעריך אותו הכהן, על פי אשר תשיג יד הנודר יעריכנו הכהן\u0003\"\u0004 (שם כז, ח) ומדגיש שם הכתוב \u0003\"הוא\"\u0004 לומר לנו שדווקא הוא דינו כן \u0003ולא בעל חוב.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 הסבור שמסדרים לבעל חוב כיצד הוא דורש \"הוא\" זה? ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 כוונתו: \u0003עד שיהא במכותו\u0004 (בעניותו) \u0003מתחילתו ועד סופו,\u0004 שאם היה עשיר מתחילה או שהתעשר לאחר מכן אין מסדרים לו.","ושואלים מצד אחר: \u0003ויחזירו\u0004 משכון \u0003בהקדש\u0004 מ\u0003קל וחומר מבעל חוב,\u0004 ונאמר כך: \u0003ומה בעל חוב שאין מסדרים\u0004 לו לאחר שלושים יום — בכל זאת \u0003מחזירים\u0004 לו את המשכון, \u0003הקדש שמסדרין\u0004 לו — \u0003אינו דין שמחזירין לו\u0004 משכון? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004השב תשיב לו את העבוט כבוא השמש \u0003ושכב בשלמתו וברכך\"\u0004 (דברים כד, יג), שדבר זה נאמר במלוה רגיל, \u0003יצא הקדש שאין צריך ברכה.\u0004","על כך תוהים: \u0003ולא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ואכלת ושבעת וברכת\u0004 את ה' אלהיך\u0003\"\u0004 (שם ח, י), משמע שאף הקודש צריך ברכה! \u0003אלא\u0004 זה הטעם: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין השבת עבוט: \u0003\"ולך תהיה צדקה\"\u0004 (שם כד, יג), ללמד: \u0003מי שצריך צדקה, יצא הקדש שאין צריך צדקה.\u0004","מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רבה בר אבוה\u0004 את \u0003אליהו\u0004 הנביא \u0003דקאי\u0004 \u0005[ש\u0006הוא \u0005עומד]\u0006 \u0003בבית הקברות של גוים.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר אבוה: \u0003מהו שיסדרו בבעל חוב? אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003גמר\u0004 \u0005[למד]\u0006 גזירה שווה \u0003\"מיכה\" \"מיכה\" מערכין; גבי\u0004 \u0005[אצל]\u0006 \u0003ערכין כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ואם מך הוא מערכך\"\u0004 (ויקרא כז,ח), \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בעל חוב כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וכי ימוך אחיך\"\u0004 (שם כה, לה)."],["\u0003מנין לערום שלא יתרום\u0004 תרומה? ענה לו: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא יראה בך ערות דבר\"\u0004 (דברים כג, טו), שאין לומר דבר קדושה כשהערוה גלויה, ואם כן אינו יכול לברך על הפרשת התרומה.","אחר כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר אבוה לאליהו: וכי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כהן הוא מר\u0004 \u0005[אדוני]?\u0006 ואם כן, \u0003מאי טעמא קאי מר\u0004 \u0005[מה טעם עומד אדוני]\u0006 \u0003בבית הקברות? אמר ליה\u0004 \u0005[לו]\u0006 אליהו: וכי \u0003לא מתני מר\u0004 \u0005[למד אדוני]\u0006 סדר \u0003טהרות?\u0004 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 שם בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן יוחי אומר: קבריהם של גוים אין מטמאין, שנאמר: \"ואתן צאני צאן מרעיתי אדם אתם\"\u0004 (יחזקאל לד, לא), ללמד: \u0003אתם קרויים \"אדם\", ואין גוים קרויים \"אדם\".\u0004 וכיון שבטומאת אהל המת נאמר בכתוב \"אדם כי ימות באהל\" (במדבר יט, יד) נלמד מכאן שכל טומאת אהל המת אינה חלה על גוי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר אבוה: וכיצד אדע ברייתא זו, הרי \u0003בארבעה לא מצינא, בשיתא מצינא\u0004 \u0005[בארבעה סדרים\u0006 הנלמדים כרגיל \u0005אין אני יכול\u0006 ללמוד, \u0005ובשישה אוכל]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 זה אינך יכול ללמוד הכל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר אבוה: \u0003דחיקא\u0004 \u0005[דחוק]\u0006 \u0003לי מילתא\u0004 \u0005[הדבר],\u0006 כלומר, דחוק אני בפרנסה, ומשום דוחק הפרנסה איני יכול ללמוד כראוי. \u0003דבריה ועייליה\u0004 \u0005[הוליכו והכניסו]\u0006 \u0003לגן עדן,\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו לרבה בר אבוה: \u0003פשוט\u0004 את \u0003גלימך\u0004 \u0005[גלימתך],\u0006 \u0003ספי שקול מהני טרפי\u0004 \u0005[לקט\u0006 ו\u0005קח מן העלים הללו]\u0006 שמונחים שם. \u0003ספא שקל\u0004 \u0005[לקט\u0006 ו\u0005לקח].\u0006","\u0003כי הוה נפיק\u0004 \u0005[כאשר יצא]\u0006 \u0003שמע\u0004 קול \u0003דקאמר\u0004 \u0005[שאומר]:\u0006 \u0003מאן קא אכיל לעלמיה\u0004 \u0005[מי אוכל,\u0006 מכלה \u0005את עולמו,\u0006 עולם הבא שלו\u0005]\u0006 \u0003כרבה בר אבוה\u0004 הנהנה מזכות עולם הבא בעולם הזה. \u0003נפץ שדנהו\u0004 \u0005[פרש\u0006 את גלימתו \u0005וזרק את העלים].\u0006 ו\u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003אתייה לגלימיה\u0004 \u0005[הביא את גלימתו]\u0006 ונתברר כי \u0003סחט גלימא ריחא\u0004 \u0005[הגלימה קלטה ריח]\u0006 כל כך טוב מן העלים ההם, עד ש\u0003זבניה בתריסר אלפי דינרי\u0004 \u0005[מכרו בשנים עשר אלף דינרים],\u0006 אבל כיון שידע זה הוא מחלקו לעולם הבא לא רצה להנות מהם, \u0003פלגינהו לחתנוותיה\u0004 \u0005[חילק אותם בין חתניו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב: \u0003\"ואם איש עני הוא לא תשכב בעבטו\"\u0004 (דברים כד, יג), ומשמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה איש \u0003עשיר\u0004 — \u0003שכיב\u0004 \u0005[\u0006\u0005שכב].\u0006 עד כאן לשון הברייתא. ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 מה פירוש הדברים? \u0003אמר רב ששת: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ואם איש עני הוא\u0004 — \u0003לא תשכב ועבוטו אצלך,\u0004 אלא החזירנו לו עם בא השמש. \u0003הא\u0004 \u0005[הרי]\u0006 אם היה איש \u0003עשיר\u0004 — \u0003שכיב\u0004 \u0005[שכב]\u0006 \u0003ועבוטו אצלך.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המלוה את חבירו אינו רשאי למשכנו, ואינו חייב להחזיר לו, ועובר בכל השמות הללו.\u0004 לשון ברייתא זו סתומה, ולכן שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירושה? \u0003אמר רב ששת: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין את הדברים: \u0003המלוה את חבירו אינו רשאי למשכנו, ואם משכנו\u0004 — \u0003חייב להחזיר לו. ועובר בכל השמות הללו\u0004 — \u0003אסיפא\u0004 \u0005[על סופם]\u0006 של הדברים נאמר, כלומר, מי שאינו מחזיר עובר בכל האזהרות הכתובות בענין זה בתורה.","\u0003רבא אמר: הכי קאמר\u0004 \u0005[כך אמר]\u0006 החכם בברייתא זו, כך יש להבין: \u0003המלוה את חבירו אינו רשאי למשכנו, ואם משכנו\u0004 — \u0003חייב להחזיר לו.\u0004 \u0003במה דברים אמורים\u0004 — \u0003שמשכנו שלא בשעת הלואתו,\u0004 אלא לוקח משכון כדי להכריחנו לשלם, \u0003אבל\u0004 אם \u0003משכנו בשעת הלואתו\u0004 שאז המשכון ניתן כערבון להלוואה — אינו חייב להחזיר לו. \u0003ועובר בכל השמות הללו\u0004 כוונתו \u0003ארישא\u0004 \u0005[על\u0006 הקטע \u0005הראשון],\u0006 שאינו רשאי למשכנו.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שיזבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא\u0004 ברייתא זו: מה שנאמר \"אם חבול תחבל שלמת רעך \u0003עד בא השמש תשיבנו לו\u0004\" (שמות כב, כה) — \u0003זו כסות לילה, \"השב תשיב לו את העבוט כבוא השמש\"\u0004 (דברים כד, יג) — \u0003זו כסות יום. אמר ליה\u0004 \u0005[לו]\u0006 רבא: תמוה הדבר, כסות \u0003דיממא בליליא\u0004 \u0005[של יום בלילה]\u0006 \u0003למה לי, ודליליא ביממא\u0004 \u0005[ושל לילה ביום]\u0006 \u0003למה לי,\u0004 ומדוע יחזירן לו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שיזבי: האם \u0003איסמייה\u0004 \u0005[אמחוק אותה]?\u0006 כלומר, האם לדעתך משובשת היא ברייתא זו וצריך למחוק אותה מגירסתי? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אל תמחק, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש: \u0003\"עד בא השמש תשיבנו לו\"\u0004 — \u0003זו כסות יום שניתנה לחבול בלילה\u0004 וצריך להחזירה ביום, ואילו \u0003\"השב תשיב לו את העבוט כבוא השמש\"\u0004 — \u0003זו כסות לילה שניתנה לחבול ביום,\u0004 וצריך להחזירה בלילה.","\u0003אמר ר' וחנן: משכנו ומת\u0004 — \u0003שומטו\u0004 המלוה את המשכון שהחזיר \u0003מעל גבי בניו,\u0004 שאין עליו חובה להשאיר את המשכון אצל הבנים. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא, \u0003אמר ר' מאיר: וכי מאחר שממשכנין למה מחזירין?\u0004 על שאלה זו תוהים: \u0003למה מחזירין?!\u0004 \u0003רחמנא אמר אהדר\u0004 \u0005[התורה אמרה החזר]!\u0006 אלא כך יש לשאול: \u0003מאחר שמחזירין\u0004"],["\u0003למה חוזרין וממשכנין,\u0004 שהרי חייב הוא להחזיר לו למחר ולמה לו לקחת? ומשיבים: \u0003שלא תהא שביעית משמטתו,\u0004 שכל עוד יש משכון על החוב אין השביעית משמטת אותו, אבל חוב בלי משכון השביעית משמטת אותו. וטעם אחר — ש\u0003לא יעשה\u0004 אותו משכון כ\u0003מטלטלין אצל בניו\u0004 ולא יוכל לקחתו מבניו, כפי שאינו יכול לקחת שאר מטלטלין בחובו של אביהם.","ונדייק מכאן: \u0003טעמא דהדר ומשכניה\u0004 \u0005[הטעם\u0006 דווקא שחזר ומשכנו] \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא הדר ומשכניה\u0004 \u0005[חזר ומשכנו]\u0006 — \u0003לא,\u0004 והרי לדברי ר' יוחנן עצם לקיחת המשכון פעם אחת כבר מקנה למלוה זכות גמורה בו!","\u0003אמר רב אדא בר מתנא: ולאו תרוצי קא מתרצת לה\u0004 \u0005[וכי\u0006 \u0005אין אתה מיישב אותה]\u0006 את הברייתא הזו ומשנה קצת את לשונה? \u0003תריץ הכי\u0004 \u0005[יישב\u0006 אותה \u0005כך],\u0006 וכך תגרוס בה: \u0003וכי מאחר שמחזירין למה ממשכנין מעיקרא\u0004 \u0005[מתחילה]\u0006 — \u0003שלא תהא שביעית משמטתו ולא יעשה\u0004 כ\u0003מטלטלין אצל בניו,\u0004 וכדברי ר' יוחנן, שכיון שלקח משכון פעם אחת כבר יכול לקחת מבניו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"\u0004כי תשה ברעך משאת מאומה \u0003לא תבא אל ביתו לעבט עבטו\"\u0004 (דברים כד, י). ומלשון הכתוב למדים שדווקא \u0003לביתו אי\u0004 \u0005[אין]\u0006 \u0003אתה נכנס, אבל אתה נכנס לביתו של\u0004 ה\u0003ערב\u0004 לחוב זה, ויכול אתה ליטול ממנו משכון. \u0003וכן הוא אומר: \"לקח בגדו כי ערב זר\"\u0004 (משלי כ, טז).","ואומר עוד בנושא זה: \u0003\"בני אם ערבת לרעך תקעת לזר כפיך. נוקשת באמרי פיך נלכדת באמרי פיך. עשה זאת אפוא בני והנצל כי באת בכף רעך לך התרפס ורהב רעיך\"\u0004 (שם ו, א–ג).","וכך הוא מפורש: ערב שנתחייב לשלם חוב, או מי שציער את חבירו בדברים (\"נוקשת באמרי פיך\"), \u0003אם ממון יש לו בידך\u0004 — \"התרפס\", ודרשוהו: \u0003התר לו פיסת יד,\u0004 כלומר, פתח את ידך ותן לו את הכסף, \u0003ואם לאו\u0004 \u0005[לא]\u0006 שאין זה חוב ממון — \"רהב רעיך\", כלומר, \u0003הרבה עליו רעים,\u0004 הבא אליו ידידים ויפייסוהו.","\u0003לצד שני,\u0004 כלומר, דבר אחר, מדרש אחר על הכתוב \"לא תבא אל ביתו\" — \u0003לביתו אי\u0004 \u0005[אין]\u0006 \u0003אתה נכנס\u0004 לקחת ממנו משכון על הלוואה, \u0003אבל אתה נכנס\u0004 ונוטל ממנו חפצים \u0003לשכר כתף\u0004 (סבל), \u0003לשכר חמר, לשכר פונדק, לשכר דיוקנאות\u0004 (ציורים) שצייר. שאפשר לכפות את השוכר לשלם משכורת ומותר לקחת ממנו משכון. \u0003יכול אפילו זקפן עליו במלוה?\u0004 שאחר שנתחייב בשכר, הסכימו שישאר הסכום בתורת מילווה — \u0003תלמוד לומר: \"משאת מאומה\"\u0004 (דברים כד, י), כלומר, שכיון שנעשה הדבר חוב — הרי הוא כשאר הלוואות, ואסור לגבות משכון בעל כורחו.","\u0003אלמנה, בין שהיא ענייה בין שהיא עשירה\u0004 — \u0003אין ממשכנין אותה, שנאמר: \"ולא תחבל בגד אלמנה (\u0004דברים כד, יז).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלמנה, בין שהיא ענייה בין שהיא עשירה אין ממשכנין אותה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר: עשירה ממשכנין אותה, ענייה\u0004 — \u0003אין ממשכנין אותה.\u0004 כי הטעם שאין ממשכנים רכוש אלמנה עניה הוא משום שאתה \u0003חייב להחזיר לה,\u0004 שהרי חייבים להחזיר לעני את משכונו בכל עת הצורך, וכיון שחייב לבוא בכל יום ולהחזיר לה הרי \u0003אתה משיאה שם רע בשכנותיה\u0004 שהשכנות רואות שגבר זר בא בכל פעם לביתה, ועלול לצאת עליה שם רע, כאילו שיש לה יחסים שאינם מהוגנים עם אותו אדם. וכיון שבעשירה אין חובת החזרת העבוט — מותר למשכן רכושה.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 על פי ברייתא זו כי \u0003ר'\u0004 \u0003יהודה לא דריש טעמא דקרא\u0004 \u0005[אינו דורש את טעם הכתוב]\u0006 ופוסק כדברי הכתוב כפי שהוא, ואילו \u0003ר'\u0004 \u0003שמעון דריש טעמא דקרא\u0004 \u0005[דורש טעם הכתוב]?\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם]\u0006 אומרים במקום אחר,","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר במצוות המלך \u0003\"ולא ירבה לו נשים\u0004 ולא יסור לבבו\u0003\"\u0004 (דברים יז, יז) \u0003ר'\u0004 \u0003יהודה אומר: מרבה הוא, ובלבד שלא יהו\u0004 נשים כאלה שהן \u0003מסירות את לבו. ר'\u0004 \u0003שמעון אומר: אפילו אחת והיא מסירה את לבו\u0004 — \u0003הרי זה לא ישאנה,\u0004 שהרי צריך שלא יסור לבו. \u0003אם כן מה תלמוד לומר \"ולא ירבה לו נשים\"\u0004 — \u0003אפילו\u0004 נשים צדקניות \u0003כאביגיל.\u0004 והרי כאן ר' שמעון הוא שאינו דורש את טעם המקראות, ור' יהודה הוא הדורש!","ומסבירים: \u0003לעולם\u0004 יש לומר כי בדרך כלל \u0003ר'\u0004 \u0003יהודה לא דריש טעמא דקרא\u0004 \u0005[\u0006הוא \u0005שאינו דורש את טעמי הכתוב],\u0006 \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 במצוות המלך, \u0003דמפרש קרא\u0004 \u0005[שמפרש הכתוב]\u0006 בעצמו את הטעם \u0003\"ולא ירבה לו נשים ולא יסור\".\u0004 שהכתוב עצמו מגביל את ההלכה ואומר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא ירבה לו נשים\u0004 — \u0003משום\u0004 ש\u0003לא יסור.\u0004","\u0003ור'\u0004 \u0003שמעון\u0004 סבור: \u0003מכדי בעלמא דרשינן טעמא דקרא\u0004 \u0005[הלא בכלל דורשים אנו את טעמו של הכתוב],\u0006 ואם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא ירבה\", ולא בעינן\u0004 \u0005[ואין אנו צריכים]\u0006 שיאמר \u0003\"לא יסור\" ואנא ידענא\u0004 \u0005[ואני אדע]\u0006 בעצמי: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא ירבה\u0004 — \u0003משום\u0004 ש\u0003לא יסור.\u0004 ואם כן, \u0003\"לא יסור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 אלא ודאי בא להוסיף איסור אחר: ש\u0003אפילו אחת ומסירה את לבו\u0004 — \u0003הרי זה לא ישאנה.\u0004 ולפי זה, יש בכתוב שתי הלכות, הלכה כללית שלא ירבה נשים, והלכה אחרת שלא ישא אשה המסירה את לבו.","\u0003החובל את הריחים,\u0004 שלוקח ריחים כמשכון — \u0003עובר משום לא תעשה\u0004 המפורש בתורה, \u0003וחייב משום שני כלים,\u0004 אם לקח את שתי אבני הריחים. \u0003שנאמר: \"לא יחבל ריחים ורכב\" (\u0004דברים כד, ו). ומוסיפים: \u0003ולא ריחים ורכב בלבד אמרו\u0004 שאסור לקחת כמשכון, \u0003אלא כל דבר שעושין בו אוכל נפש\u0004 אסור לקחת, \u0003שנאמר: \"כי נפש הוא חבל\"\u0004 (שם).","\u0003אמר רב הונא: חבל ריחים\u0004 — \u0003לוקה שתים,\u0004 שתי פעמים מלקות, \u0003משום ריחים,\u0004 שנאמר שלא יחבול ריחים, \u0003ומשום \"כי נפש הוא חבל\"\u0004 שהרי לקח דבר המשמש לצורך האוכל. אם לקח \u0003ריחים ורכב\u0004 — \u0003לוקה שלש; משום רחים,\u0004 \u0003ו\u0004משום \u0003רכב,\u0004 ו\u0003משום \"כי נפש הוא חבל\".\u0004","\u0003ו\u0004אילו \u0003רב יהודה אמר: חבל ריחים\u0004 — \u0003לוקה אחת,\u0004 חבל \u0003רכב\u0004 — \u0003לוקה אחת,\u0004 חבל \u0003ריחים ורכב\u0004 — \u0003לוקה שתים.\u0004 ואילו מה שנאמר \u0003\"כי נפש הוא חבל\"\u0004"],["\u0003לשאר דברים הוא דאתא\u0004 \u0005[שבא]\u0006 ללמדנו שכל מכשירים שעושים בהם אוכל נפש אסור לחבול.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003אביי ורבא\u0004 שנחלקו בנושא אחר, \u0003בפלוגתא\u0004 \u0005[במחלוקתם]\u0006 של \u0003רב הונא ורב יהודה קמיפלגי\u0004 \u0005[חולקים]\u0006 הם? שנחלקו בענין אכילת בשר קרבן פסח שלא צלו אותו כדין, שכן אמר הכתוב \"אל תאכלו ממנו נא ובשל מבושל במים כי אם צלי אש ראשו על כרעיו ועל קרבו\" (שמות יב, ט).","ש\u0003אמר רבא: אכל נא\u0004 (צלוי למחצה) — \u0003לוקה שתים,\u0004 לוקה \u0003משום\u0004 \u0003\"\u0004אל תאכלו ממנו \u0003נא\", ו\u0004לוקה \u0003משום \"\u0004אל תאכלו ממנו... \u0003כי אם צלי אש\"\u0004 (שם). \u0003ו\u0004אם אכל בשר פסח \u0003מבושל\u0004 — \u0003לוקה שתים: משום \"מבשל\" ומשום \"כי אם צלי אש\".\u0004 ואם היה גם \u0003נא ו\u0004גם \u0003מבושל\u0004 — \u0003לוקה שלש: משום \"נא\", ומשום \"מבשל\" ומשום \"לא תאכלנו כי אם צלי אש\".\u0004","ואילו \u0003אביי אמר: אין לוקים על לאו שבכללות.\u0004 כי הלאו הזה \"אל תאכלו ממנו נא ובשל מבושל במים כי אם צלי אש\" איננו מיוחד לענין אחד, אלא כולל בתוכו עניינים רבים ואין לוקים על לאו שאין בו איסור של דבר מסויים ומיוחד. ולכאורה אביי ורבא חלוקים באותו נושא של רב הונא ורב יהודה. \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003אביי\u0004 ש\u0003אמר כרב יהודה, ורבא\u0004 ש\u0003אמר כרב הונא?\u0004","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא:\u0004 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי — \u0003אפילו כ\u0004דעת \u0003רב יהודה\u0004 אמרתי, כי יש להבדיל בין הנושאים; \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רב יהודה התם\u0004 \u0005[שם]\u0006 שאין לוקים על \"כי נפש הוא חובל\" משום שהמלים \u0003\"כי נפש הוא חבל\" לא משמע\u0004 אין פירושן כשלעצמן \u0003ריחים ורכב\u0004 אלא הן הוראה כללית, ולכן מסתבר כי \u0003לשאר דברים הוא דאתא\u0004 \u0005[שבא]\u0006 ולא להוסיף איסור על ריחים ורכב.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003\"כי אם צלי אש\" למאי אתא\u0004 \u0005[למה בא]?\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003ללאו.\u0004 הלא משמעותו היא רק להוציא או נא או מבושל, ואם כך אפשר לומר שיש בכך איסור מסויים ואיסור נוסף על הדברים המנויים שם.","\u0003ואביי אמר\u0004 \u0003לך אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו לרב הונא\u0004 אמרתי אותם. כיצד, \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רב הונא התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 ש\u0003\"כי נפש הוא חבל\"\u0004"],["\u0003יתירא הוא\u0004 \u0005[יתר הוא]\u0006 ובא להוסיף הלכות חדשות לגבי שאר מכשירים, \u0003כיון דיתירא\u0004 \u0005[שמיותר]\u0006 \u0003הוא\u0004 — \u0003שדייה\u0004 \u0005[הטל אותו]\u0006 \u0003הוא\u0004 על \u0003ריחים ורכב. אבל הכא\u0004 \u0005[כאן]\u0006 בענין הפסח, הביטוי \u0003\"כי אם צלי אש\"\u0004 (שמות יב ט) \u0003לאו יתירא הוא\u0004 \u0005[לא מיותר]\u0006 \u0003הוא,\u0004 \u0003דמבעי ליה לכדתניא\u0004 \u0005[שנחוץ הוא ללמוד לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בשעה שישנו\u0004 הציווי \u0003בקום אכול צלי,\u0004 כלומר, בשעת הלילה כשחלה מצות אכילת הפסח — באותה שעה \u0003ישנו\u0004 גם \u0003ב\u0004איסור \u0003\"בל תאכל נא\",\u0004 אבל \u0003בשעה שאינו בקום אכול צלי,\u0004 כגון קודם לכן — \u0003אינו ב\"בל תאכל נא\",\u0004 ואם אכלו אז — אינו לוקה.","","לגופה של המחלוקת בריחים ורכב מעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה:\u0004 אם \u0003חבל זוג\u0004 (מספריים) \u0003של ספרים,\u0004 או \u0003צמד של פרות\u0004 — \u0003חייב שתים.\u0004 לקח \u0003זה בעצמו וזה בעצמו,\u0004 להב אחד של מספריים או פרה אחת — \u0003אינו חייב אלא אחת.\u0004 הרי שאינו לוקה אלא אחת ואינו לוקה על הלאו הכולל.","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת] :\u0006 \u0003חבל זוג של ספרים וצמד של פרות, יכול לא יהא חייב אלא אחת\u0004 — \u0003תלמוד לומר \"לא יחבל ריחים ורכב\"\u0004 (דברים כד, י), ונלמד: \u0003מה ריחים ורכב שהן מיוחדין,\u0004 שהם אמנם \u0003שני כלים\u0004 כל אחד לעצמו \u0003ועושין\u0004 יחד \u0003מלאכה אחת\u0004 — ובכל מקום \u0003חייב על זה בפני עצמו ועל זה בפני עצמו, אף כל דברים שהן שני כלים מיוחדים,\u0004 כמו זוג של ספרים או צמד של פרות \u0003ועושין מלאכה אחת\u0004 — \u0003חייב על זה בפני עצמו ועל זה בפני עצמו.\u0004","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003חבל סכינא דאשכבתא מחבריה\u0004 \u0005[סכין של שחיטה אצל חבירו].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אביי\u0004 לשאול בענין זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003זיל אהדריה\u0004 \u0005[לך החזר אותו],\u0006 \u0003דהוי ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כלי שעושים בו אוכל נפש\u0004 וכאמור — אסור לך לקחתו כמשכון, \u0003ותא קום בדינא עלה\u0004 \u0005[ולך עמוד בדין עליה].\u0006 \u0003רבא אמר\u0004 שהוא \u0003לא צריך למקם בדינא עלה\u0004 \u0005[לעמוד בדין עליה],\u0006 שמאחר והסכין נמצאה כבר בידו \u0003ויכול לטעון עד כדי דמיהן,\u0004 יכול הוא לטעון שההוא חייב לו כדי שיעור זה. ושואלים: \u0003ו\u0004כי \u0003אביי לית ליה ההיא סברא\u0004 \u0005[אין לו,\u0006 אינו מקבל \u0005אותה סברה]\u0006 שמי שתפס חפץ של בעל חוב, שיכול לטעון בחוב עד כדי דמיו? \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004אותו מעשה שהיה ב\u0003הנהו עיזי דאכלי חושלא\u0004 \u0005[אותן עיזים שאכלו שעורים קלופות]\u0006 \u0003בנהרדעא, ואתא מרא דחושלא\u0004 \u0005[ובא בעל השעורים]\u0006 \u0003ותפס להו\u0004 \u0005[אותם,\u0006 את העיזים\u0005],\u0006 \u0003וקא טעין טובא\u0004 \u0005[וטען\u0006 שחייב לו אותו אדם \u0005הרבה].\u0006 \u0003ואמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל\u0004 שהיה דיין שם ש\u0003יכול לטעון עד כדי דמיהן!\u0004","","ומסבירים שיש הבדל: \u0003התם לאו מידי דעבדא לאושולי ולאוגורי\u0004 \u0005[שם\u0006 העיזים \u0005אינו דבר שעשוי להשאיל ולהשכיר]\u0006 \u0003הוא,\u0004 ולכן אם הוא מחזיק בהן יש לו זכות לכאורה עליהן, ויכול להסתמך על חזקה זו. ואילו \u0003הכא מידי דעביד לאושולי ולאוגורי\u0004 \u0005[כאן\u0006 השכיר \u0005דבר שעשוי להשאיל ולהשכיר]\u0006 \u0003הוא,\u0004 ובדבר כגון זה אינו נאמן אם מחזיק בו בלא ראיה. שכן \u0003שלח רב הונא בר אבין\u0004 הלכה זו: \u0003דברים העשויין להשאיל ולהשכיר, ואמר\u0004 אדם המחזיק בהן: \u0003לקוחין הן בידי\u0004 (קניתי אותן) \u0003אינו נאמן\u0004 בטענה זו בלבד, וצריך להביא ראיות אחרות, כי אולי באו לידו בשאלה או בשכירות. ושואלים: \u0003ו\u0004כי \u0003רבא לית ליה האי סברא\u0004 \u0005[אין לו,\u0006 אינו מקבל \u0005סברה זו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו \u0003אפיק זוגא דסרבלא וספרא דאגדתא מיתמי\u0004 \u0005[הוציא מספריים של צמר וספר אגדה מיתומים]\u0006 שהחזיקו בהם מפני שהם \u0003דברים העשויין להשאיל ולהשכיר!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומ]\u0006 \u0003לך רבא:\u0004 \u0003האי נמי\u0004 \u0005[זו גם כן],\u0006 סכין שחיטה, \u0003כיון דמיפגמא\u0004 \u0005[ש\u0006היא \u0005נפגמת]\u0006 — \u0003קפדי אינשי ולא מושלי\u0004","",""],["\u0003הבית והעלייה של שנים,\u0004 שלאחד היה שייך הבית בקומה התחתונה ולשני העליה, \u0003שנפלו\u0004 — \u0003שניהם חולקין בעצים ובאבנים ובעפר\u0004 של המפולת. \u0003ורואין אלו אבנים העשויות להשתבר\u0004 ולפי זה מורידים את האבנים הללו מחשבונו של אותו אדם ששלו נשברו. \u0003אם היה אחד מהן מכיר מקצת אבניו\u0004 — \u0003נוטלן\u0004 לעצמו \u0003ו\u0004אולם הן \u0003עולות לו מן החשבון,\u0004 שהשותף יכול ליטול אבנים אחרות כנגדן.","\u0003מדקתני\u0004 \u0005[ממה ששנה\u0006\u0005]\u0006 במשנה: \u0003רואין\u0004 אלו אבנים עשויות להשתבר — \u0003מכלל\u0004 הדברים אתה למד שמדובר כאן באופן \u0003דאיכא למיקם עלייהו\u0004 \u0005[שאפשר לעמוד עליהן\u0006\u0005],\u0006 לראות לפי האבנים כיצד אירע הדבר, \u0003אי בחבסא נפיל\u0004 \u0005[אם ברביצה נפל\u0006\u0005],\u0006 שקומת הקרקע היא שהתמוטטה והעליונה נפלה מחמתה, \u0003אי בחבטא נפיל\u0004 \u0005[אם בחבטה נפל\u0006\u0005],\u0006 שהעלייה התמוטטה ועל ידי כך גרמה שנפלה גם הקומה התחתונה.","ואם אפשר להבחין בדבר, \u0003אי הכי רישא אמאי\u0004 \u0005[אם כך, בראש\u0006 המשנה \u0005מדוע\u0006\u0005]\u0006 \u0003חולקים\u0004 בשווה? \u0003נחזי\u0004 \u0005[נראה\u0006\u0005],\u0006 \u0003אי בחבטא נפיל\u0004 \u0005[אם בחבטה נפל\u0006 הבית\u0005]\u0006 — \u0003עלייתא איתבור\u0004 \u0005[העלייה נשברה\u0006\u0005]\u0006 ואבניה הן השבורות, \u0003אי בחבסא נפיל\u0004 \u0005[אם ברביצה נפל\u0006\u0005]\u0006 — \u0003תתייתא איתבור\u0004 \u0005[התחתונות נשברו\u0006\u0005]!\u0006","ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 \u0003דנפיל בליליא\u0004 \u0005[שנפל\u0006 הבית \u0005בלילה\u0006\u0005]\u0006 ולא ראו כיצד נפל. ושואלים: \u0003ולחזינהו בצפרא\u0004 \u0005[ושיראו את\u0006 האבנים \u0005בבוקר]\u0006 וידעו כיצד נפל הבית? ומשיבים: \u0003דפנינהו\u0004 \u0005[שפינו אותן,\u0006 את האבנים\u0005]\u0006 ממקומן, ואין איפוא לדעת. ושואלים: \u0003וליחזי מאן פנינהו ולשייליה\u0004 \u0005[ושיראו מי פינה אותן וישאלו אותו\u0006\u0005]\u0006 כיצד נפל הבית? ומשיבים: \u0003דפנינהו\u0004 \u0005שפינו אותן]\u0006 \u0003בני רשות הרבים ואזלו לעלמא\u0004 \u0005[והלכו\u0006 להם \u0005לעולם,\u0006 למקום אחר\u0005]\u0006 ועתה אין אפשרות לברר פרט זה.","ושואלים: \u0003וליחזי ברשות דמאן יתבן\u0004 \u0005[שיראה ברשותו של מי\u0006 מהם \u0005נמצאות\u0006\u0005]\u0006 האבנים, \u0003וליהוי אידך\u0004 \u0005[ושיהיה האחר\u0006\u0005]\u0006 \u0003המוציא מחבירו עליו הראיה!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006\u0005],\u0006 אלא לאופן \u0003דייתבן\u0004 \u0005[ש\u0006האבנות \u0005מצויות]\u0006 \u0003בחצר דתרוייהו\u0004 \u0005[של שניהם\u0006\u0005],\u0006 \u0003אי נמי\u0004 \u0005[או גם כן\u0006\u0005]\u0006 שנפלו \u0003ברשות הרבים. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]:\u0006 \u0003שותפים בכי האי גוונא לא קפדי אהדדי\u0004 \u0005[בכגון זה אינם מקפידים זה על זה\u0006\u0005]\u0006 שיחלקו את החצר כך שלא ירשו איש לחבירו להניח שם דברים, ואם כן אין מחלוקת החצר הוכחה לענין האבנים.","שנינו במשנה ש\u0003אם היה אחד מהן מכיר\u0004 את אבניו — נוטלן. ושואלים: \u0003והלה,\u0004 והאחר, \u0003מה טוען? אי\u0004 \u0005[אם]\u0006 מדובר באופן \u0003דקאמר\u0004 \u0005[שהוא אומר]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 של חבירי הן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם השני מסכים מה מקום יש לדון בכך? \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אמר אין\u0004 \u0005[כן\u0006\u0005],\u0006 \u0003למה נוטל\u0004 השני ומה ראיה יש לו?! \u0003אלא,\u0004 יש לומר \u0003דאמר ליה\u0004 \u0005[שאומר לו\u0006\u0005]\u0006 השני: \u0003איני יודע,\u0004 וסומכים משום כך על האחר שטוען שהוא בטוח בדבר.","ומציעים: \u0003לימא תהוי תיובתא\u0004 \u0005[האם לומר שתהא זו קושיה חמורה]\u0006 ל\u0003רב נחמן,\u0004 \u0003דאיתמר\u0004 \u0005[שנאמר\u0006\u0005]\u0006 שחלקו אמוראים בבעיה הבאה: אמר אחד לחבירו: \u0003מנה לי בידך\u0004 שאתה חייב לי, \u0003והלה,\u0004 הנתבע \u0003אומר: איני יודע. רב הונא ורב יהודה אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003חייב\u0004 לשלם לו, לפי שאינו מכחיש. \u0003רב נחמן ו\u0004\u0003ר' יוחנן אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003פטור.\u0004 ומענייננו לכאורה ראיה ש\"איני יודע\" הוא כהודאה!","ודוחים: \u0003כדאמר\u0004 \u0005[כפי שאמר\u0006\u0005]\u0006 \u0003רב נחמן\u0004 בתירוץ לקושיה דומה באותו נושא: מתי חייב הוא לשלם — \u0003כגון שיש עסק שבועה ביניהן,\u0004 שמכיון שחייב להשבע דורשים ממנו להשבע גם על דבר זה, וכיון שאינו יכול להשבע על כך משלם. \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 מדובר \u0003כגון שיש עסק שבועה ביניהן.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006\u0005]\u0006 \u0003עסק שבועה\u0004 זה? ומשיבים: \u0003כ\u0004\u0003ד\u0004ברי \u0003רבא\u0004 ש\u0003אמר רבא,\u0004 אמר לחבירו: \u0003מנה לי בידך, והלה,\u0004 הנתבע \u0003אומר: אין לך בידי אלא חמשים\u0004 שאני בטוח בהם, \u0003והשאר,\u0004 החמישים אחרים, \u0003איני יודע.\u0004 והרי מדין תורה צריך הוא להשבע על השאר, שהריהו מודה מקצת הטענה ומודה במקצת נשבע — \u0003מתוך שאינו יכול לישבע\u0004 שהרי אינו יודע, על כן בעל כורחו \u0003ישלם.\u0004","שנינו במשנה שהמכיר את אבניו לוקח לו את אלה שהוא מכירן, והאחר נוטל כנגדו מן האבנים השבורות, והאבנים הללו \u0003עולות לו מן החשבון. סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רבא למימר\u0004 \u0005[לומר\u0006\u0005]\u0006 שהכוונה היא \u0003לפי חשבון\u0004 ה\u0003שבורות.\u0004 \u0003אלמא\u0004 \u0005[מכאן\u0006\u0005]\u0006 \u0003כיון\u0004 ש\u0003אמר\u0004 \u0003איני יודע,\u0004 כפי שסכמנו קודם בפירוש הענין \u0003ריע טפי\u0004 \u0005[גרוע\u0006 מצבו \u0005יותר\u0006\u0005]\u0006 מבחינה הלכתית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אדרבה\u0004 \u0005[להיפך\u0006\u0005],\u0006 \u0003הא ריע טפי\u0004 \u0005[זה,\u0006 הצד השני, \u0005גרוע יותר\u0006\u0005].\u0006 \u0003מדהני ידע, טפי לא ידע\u0004 \u0005[מכיון שאת אלה הוא יודע,\u0006 מכיר\u0005],\u0006 אם כן \u0003תו לית ליה\u0004 \u0005[שוב אין לו]\u0006 זכות באבנים אחרות, \u0003ואידך כולהו\u0004 \u0005[ו\u0006כל \u0005האחרות כולן]\u0006 \u0003דהיאך נינהו\u0004 \u0005[של השני הן\u0006\u0005]!\u0006","\u0003אלא אמר אביי: לפי חשבון\u0004 ה\u0003שלימות,\u0004 שהשני לוקח כנגדן אבנים שלמות אחרות. שואלים: \u0003אי הכי מאי קמהני ליה\u0004 \u0005[אם כן, מה הוא נהנה\u0006 מרויח מכך\u0005]\u0006 שהוא מכיר את אבניו שלו? ומשיבים: \u0003למלבנא רווחא\u0004 \u0005[למלבן מרווח\u0006\u0005],\u0006 שהיה המלבן — דפוס הלבנים הללו — רחב יותר במקצת. \u0003אי נמי טינא דמעבדא\u0004 \u0005[או גם כן\u0006 שהיה \u0005טין מעובד],\u0006 שהטיט שממנו עשו את הלבנים מעובד בצורה טובה יותר, ולכן הוא נהנה כשלוקח את הלבנים הללו.","\u0003הבית והעלייה\u0004 והיה הדייר בעלייה שוכר הדר בבית זה, \u0003ו\u0004\u0003נפחתה\u0004 (נשברה או נשמטה למטה) \u0003העלייה, ואין בעל הבית,\u0004 המשכיר, \u0003רוצה לתקן\u0004 — \u0003הרי בעל העלייה,\u0004 השוכר, \u0003יורד ודר למטה\u0004 בבית, \u0003עד שיתקן לו\u0004 בעל הבית \u0003את העלייה.\u0004","\u0003ר' יוסי אומר:\u0004 בבית השייך לשותפים אשר נפחת הגג, \u0003התחתון נותן את התקרה\u0004 עצמה של קורות או אבנים, \u0003והעליון את המעזיבה,\u0004 כיסוי הטיט שעליה.","ושואלים: מה שאמרנו ש\u0003נפחתה\u0004 העלייה, \u0003בכמה?\u0004 מהו שיעור של שבירה שיכול בעל העלייה לומר ששוב אינו יכול לגור שם? \u0003רב אמר: ברובה, שמואל אמר: בארבעה\u0004 טפחים כבר נקרא פחות.","ומבארים את טעם הדברים: \u0003רב אמר\u0004 כי נפחתה \u0003ברובה, אבל בארבעה\u0004 — \u0003לא.\u0004 ומדוע — \u0003אדם דר חציו למטה וחציו למעלה.\u0004 כלומר, גם אם חלק מן הדירה נמוך יותר אפשר עוד לדור בדירה. \u0003ושמואל אמר בארבעה,\u0004 מדוע — \u0003אין אדם דר חציו למטה וחציו למעלה.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר\u0006\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר\u0004 השוכר בשעת השכירות שהוא לוקח \u0003\"עלייה זו\",\u0004 הלא \u0003אזדא\u0004 \u0005[הלכה,\u0006 אבדה\u0005]\u0006 זכותו, שהרי עדיין זו היא אותה עלייה. \u0003אלא\u0004 ש\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003\"עלייה\" סתם,\u0004 ואולם אם כך אמר ודאי לעלייה שלמה וטובה התכוון ואם כן \u0003לוגר ליה אחריתי\u0004 \u0005[שישכור לו\u0006 בעל הבית \u0005עלייה אחרת\u0006\u0005]\u0006 לדור בה!","\u0003אמר רבא: לא צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 אלא במקרה ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"עלייה זו שאני משכיר לך, כי סלקא\u0004 \u0005[כאשר עולה]\u0006 — \u0003סליק בהדה\u0004 \u0005[עלה איתה],\u0006 \u0003וכי נחית\u0004 \u0005[וכאשר יורדת]\u0006 — \u0003חות בהדה\u0004 \u0005[\u0006\u0005רד איתה\u0006\u0005]\u0006 \u0003\".\u0004 ותוהים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 שפירש ואמר לו \u0003מאי למימרא\u0004 \u0005[מה יש לומר\u0006 כאן\u0005]\u0006? שהרי היה זה תנאי מפורש!","\u0003אלא אמר רב אשי:\u0004 מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בלשון זו: \u0003\"עלייה זו שעל גבי בית זה אני משכיר לך\", דהא שעביד\u0004 \u0005[ש\u0006בכך \u0005הרי שיעבד\u0006\u0005]\u0006 את ה\u0003בית לעלייה.\u0004","\u0003וכי הא\u0004 \u0005[וכמו מעשה\u0006 זה\u0005]\u0006 ש\u0003אמר רבין בר רב אדא אמר\u0004 \u0003ר' יצחק: מעשה באחד שאמר לחבירו \"דלית\u0004 (ענף גפן) \u0003שעל גבי פרסק (\u0004עץ אפרסק) \u0003זה\u0004 \u0003אני מוכר לך\u0004 \u0003\",\u0004 \u0003ונעקר הפרסק.\u0004 \u0003ובא מעשה לפני\u0004 \u0003ר' חייא ואמר: חייב אתה להעמיד לו פרסק\u0004 ולהחזיק את ענף הגפן \u0003כל זמן שהדלית קיימא\u0004 \u0005[קיימת,\u0006 עומדת\u0005].\u0006","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003ר'\u0004 \u0003אבא בר ממל:\u0004"],["אותו דייר של העלייה הדר עכשיו בבית, \u0003כשהוא דר\u0004 שם, האם \u0003לבדו הוא דר כדמעיקרא\u0004 \u0005[כמו מתחילה\u0006\u0005]\u0006 שהיה גר בעלייתו לבדו, ובעל הבית יוצא בעל כורחו, \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003שניהם דרין\u0004 שם, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הבית: \u0003אדעתא לאפקינן\u0004 \u0005[על דעת להוציאני]\u0006 מדירתי \u0003לא אגרי\u0004 \u0005[השכרתי]\u0006 \u0003לך.\u0004","\u0003אם תמצא לומר\u0004 ותחליט כי \u0003שניהם דרין בו, כשהוא,\u0004 הדייר מן העלייה, \u0003משתמש\u0004 בבית — האם \u0003דרך\u0004 ה\u0003פתחים\u0004 הקבועים בו הוא \u0003משתמש\u0004 כבעל הבית, \u0003או דרך גגין\u0004 (גגות) הוא \u0003משתמש,\u0004 שעולה בדרך המדרגות לדירתו הקודמת, ויורד לדירה התחתונה? \u0003מי אמר\u0004 \u0005[האם אומר]\u0006 בעל הבית כי גם עכשיו לא יכנס השוכר לבית אלא \u0003כדמעיקרא\u0004 \u0005[\u0006\u0005מתחילה\u0006\u0005];\u0006 \u0003מה מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 הוא נכנס \u0003דרך גגין,\u0004, כלומר, דרך העלייה, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן\u0006\u0005]\u0006 יכנס \u0003דרך גגין. או דלמא מצי אמר ליה\u0004 \u0005[שמא יכול לומר לו\u0006 השוכר\u0005]\u0006 \u0003עלייה\u0004 — \u0003קבילי עלאי\u0004 \u0005[קיבלתי עלי\u0006\u0005]\u0006 שהסכמתי לעלות במדרגות לדירתי, ואולם \u0003עלייה וירידה לא קבילי עלאי\u0004 \u0005[קבלתי עלי\u0006\u0005],\u0006 ובדרך זו צריך אני לעלות לגג ולרדת ממנו.","\u0003אם תמצא לומר\u0004 כי \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 השוכר \u0005לומר לו]\u0006 לבעל הבית: \u0003עלייה וירידה לא קבילי עלאי\u0004 \u0005[קיבלתי עלי],\u0006 אם היו \u0003שתי עליות זו על גב זו מהו?\u0004 ומפרטים: \u0003איפחית\u0004 \u0005[נפחתה]\u0006 העלייה ה\u0003עליונה\u0004 ששכר \u0003—\u0004 \u0003נחית\u0004 \u0005[יורד]\u0006 \u0003ודר ב\u0004עלייה ה\u0003תחתונה,\u0004 ואולם אם \u0003איפחית\u0004 \u0005[נפחתה]\u0006 העלייה ה\u0003תחתונה\u0004 ששכר אותה, \u0003מהו\u0004 הדין, \u0003האם\u0004 \u0003למיסלק\u0004 \u0005[עולה]\u0006 הוא \u0003לגמרי בעליונה,\u0004 ומקבל את העלייה הגבוהה יותר, או שמא יורד לדור בקומת הקרקע?","\u0003מי אמרינן דאמר ליה\u0004 \u0005[האם אומרים אנו שאומר לו]\u0006 בעל הבית: \u0003שם עלייה קבילית עלך\u0004 \u0005[קיבלת עליך],\u0006 והרי אתה גר בעלייה. \u0003או דלמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003חד עלייה\u0004 \u0005[עלייה אחת]\u0006 — \u0003קביל עליה\u0004 \u0005[קיבל עליו],\u0006 \u0003שתי עליות\u0004 — \u0003לא קביל עליה\u0004 \u0005[קיבל עליו\u0006\u0005]?\u0006 לאף אחת מהשאלות הללו לא נמצא פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה ש\u0003ר' יוסי אומר: התחתון נותן את התקרה\u0004 והעליון את המעזיבה. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"תקרה\"\u0004 לענין זה? \u0003ר' יוסי בר חנינא אמר: קינים וסנאין\u0004 \u0005[מחצלות וקורות\u0006\u0005],\u0006 \u0003ו\u0004החכם \u0003סטיני\u0004 שהיה תלמידו של ריש לקיש \u0003אמר\u0004 בשם \u0003ר' שמעון בן לקיש\u0004 רבו: \u0003לווחים\u0004 — לוחות עץ רחבים. ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים\u0006 בהלכה\u0005],\u0006 אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה\u0006 כמנהג \u0005מקומו וחכם זה כ\u0006מנהג \u0005מקומו\u0006\u0005],\u0006 שלפי דרכי הבניה של תקרה במקומות שונים אמרו מה נחוץ לתקרה.","מסופר: \u0003הנהו בי תרי דהוו דיירי, חד עילאי וחד תתאי\u0004 \u0005[שנים שהיו גרים\u0006 בבית, \u0005אחד למעלה ואחד למטה\u0006\u0005].\u0006 \u0003איפחית\u0004 \u0005נפחתה,\u0006 נתקלקלה ה\u0003מעזיבה.\u0004 \u0003כי משי מיא עילאי אזלי ומזקי לתתאי\u0004 \u0005[כאשר היה רוחץ מים העליון,\u0006 היו המים \u0005הולכים ומזיקים לתחתון\u0006\u0005],\u0006 והשאלה היתה \u0003מי מתקן\u0004 את המעזיבה. \u0003ר' חייא בר אבא אמר: העליון מתקן, ור' אלעי משום\u0004 (בשם) \u0003ר' חייא ב\u0004\u0003ר' יוסי אמר: התחתון מתקן.\u0004 ומעירים, \u0003וסימן\u0004 שלא תחליף את דעות החולקים: \u0003\"ויוסף הורד מצרימה\" (\u0004בראשית לט, א), כלומר, ר' חייא בר' יוסי, שסימנו יוסף, הוא הסבור שהתחתון (\"הורד\") מתקן.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר\u0006\u0005]\u0006 ש\u0003ר' חייא בר אבא ו\u0004\u0003ר' אלעי בפלוגתא\u0004 \u0005[במחלוקת\u0006\u0005]\u0006 של התנאים \u0003ר' יוסי ורבנן\u0004 במשנתנו, \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006? וכך נסביר: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003העליון\u0004 הוא ש\u0003מתקן,\u0004 טעמו כי \u0003קסבר\u0004 \u0005[סבור]\u0006 ש\u0003על המזיק להרחיק את עצמו מן הניזק\u0004 והיא דעת ר' יוסי במשנתנו, האומר שהעליון צריך לתת את המעזיבה, ובוודאי טעמו כדי שהמים מלמעלה לא יזיקו למטה. \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר\u0006\u0005]\u0006 שה\u0003תחתון\u0004 הוא ש\u0003מתקן, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כדעת חכמים ש\u0003על הניזק להרחיק את עצמו מן המזיק.\u0004","על הסבר זה מקשים: \u0003ותיסברא\u0004 \u0005[וכי סבור אתה\u0006\u0005]\u0006 כי \u0003ר' יוסי ורבנן\u0004 שחלקו במשנתנו \u0003לענין\u0004 הרחקת \u0003נזקין פליגי\u0004 \u0005[חלוקים הם\u0006\u0005]?\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים \u0005שמענו אותם\u0006\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מרחיקין את האילן מן הבור עשרים וחמש אמה\u0004 לפי ששרשי האילן מזיקים לבור, \u0003ובחרוב ובשקמה\u0004 ששרשיהם מתפשטים הרבה — \u0003חמשים אמה, בין מלמעלה\u0004 שהשדה שבו הבור גבוה מן השדה שבו האילן, \u0003בין מן הצד.\u0004 ו\u0003אם הבור קדם\u0004 לאילן — \u0003קוצץ\u0004 בעל הבור את האילן \u0003ונותן\u0004 לבעליו \u0003דמים\u0004 תמורתו. ו\u0003אם האילן קדם\u0004 — \u0003לא יקוץ.\u0004 ודין זה הוא דווקא כשרוצים שניהם זה לנטוע וזה לחפור, אבל אם \u0003ספק זה קדם ספק זה קדם\u0004 — \u0003לא יקוץ\u0004 את האילן.","\u0003ר' יוסי אומר: אף על פי שהבור קודמת לאילן\u0004 — \u0003לא יקוץ\u0004 בעל הבור את האחלן, לפי \u0003שזה\u0004 בעל הבור \u0003חופר בתוך שלו, וזה,\u0004 בעל האילן, \u0003נוטע בתוך שלו,\u0004 ואין בעל הבור יכול לטעון שנגרם לו נזק, אלא אם רוצה להמנע מנזק — יעשה הוא במקום אחר. \u0003אלמא\u0004 \u0005[מכאן\u0006\u0005]\u0006 ש\u0003ר' יוסי סבר\u0004 \u0005[סבור]\u0006 ש\u0003על הניזק להרחיק את עצמו\u0004 מהמזיק, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 ש\u0003על המזיק להרחיק את עצמו\u0004 מהניזק!","\u0003אלא, אי איכא למימר\u0004 \u0005[אם יש\u0006 בכלל מקום \u0005לומר\u0006\u0005]\u0006 \u0003פליגי\u0004 \u0005[שחולקים הם\u0006\u0005]\u0006 האמוראים לפי מחלוקת תנאים, הרי באמת \u0003בפלוגתא\u0004 \u0005במחלוקת\u0006 של \u0003ר' יוסי ורבנן דהתם קמיפלגי\u0004 \u0005[וחכמים של שם חלוקים הם\u0006\u0005],\u0006 שבאמת שייך הדבר למחלוקת היסודית מי מרחיק את עצמו, ואין לכך כל קשר עם המחלוקת במשנתנו.","ושואלים: אם כן, \u0003ו\u0004\u0003ר' יוסי ורבנן דהכא\u0004 \u0005[וחכמים של כאן\u0006\u0005]\u0006 במשנתנו, \u0003במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו\u0006\u0005]?\u0006 ומשיבים: \u0003בחוזק תקרה קמיפלגי\u0004 \u0005[חלוקים הם\u0006\u0005].\u0006 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים\u0006\u0005]:\u0006 \u0003מעזיבה אחזוקי\u0004 \u0005[חיזוק\u0006\u0005]\u0006 \u0003תקרה הוא,\u0004 שעיקר תפקיד המעזיבה הוא לצורך התקרה וחיזוקה, \u0003ואחזוקי\u0004 \u0005[וחיזוק]\u0006 ה\u0003תקרה\u0004 מוטל \u0003על התחתון,\u0004 שהוא \u0003בעי לאחזוקי\u0004 \u0005[צריך לחזק\u0006 אותה\u0005].\u0006 \u0003ו\u0004\u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003מעזיבה אשוויי\u0004 \u0005[השוואת]\u0006 \u0003גומות\u0004 \u0003הוא\u0004 שעושים מעזיבה כדי שיהא השטח שעל התקרה ישר וחלק, \u0003ואשוויי\u0004 \u0005[והשוואת]\u0006 ה\u0003גומות על העליון לאשוויי\u0004 \u0005[להשוות\u0006\u0005].\u0006","על סיכום זה של הנושא שואלים: \u0003איני\u0004 \u0005[וכי כן\u0006 הוא\u0005]\u0006? \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003רב אשי: כי הוינא בי\u0004 \u0005[כאשר\u0006 הייתי בבית מדרשו\u0005]\u0006 של \u0003רב כהנא\u0004 \u0003הוה אמרינן\u0004 \u0005[היינו אומרים\u0006 בישיבה\u0005]:\u0006 \u0003מודה\u0004 \u0003ר' יוסי בגירי דיליה\u0004 \u0005[בחיצים שלו\u0006\u0005],\u0006 שאף שאמר שעל הניזק להרחיק את עצמו, דבר זה נאמר רק כאשר המזיק אינו עושה מעשה. אבל אם המזיק עושה פעולה הגורמת נזק במרחק הריהו כיורה חיצים, ובמקרה כזה ודאי שהוא חייב להרחיק. והרי אף כאן המים נשפכים בידי הדייר העליון ומזיקים והריהם כחיציו!","ומשיבים: \u0003דפסקי מיא\u0004 \u0005[שפוסקים המים\u0006\u0005],\u0006 שבמקום שהוא שופך שם אין חור שהמים נשפכים ממנו במישרין למטה, אלא המים נשפכים במקום אחד בדירה \u0003והדר נפלי\u0004 \u0005[וחוזרים ונופלים\u0006\u0005]\u0006 במקום שיש פתח במעזיבה. ונמצא שאף שם אינו גורם נזק ישיר.","\u0003הבית והעלייה של שנים שנפלו,\u0004 ו\u0003אמר בעל העלייה לבעל הבית לבנות\u0004 הכל מחדש \u0003והוא אינו רוצה לבנות\u0004 — \u0003הרי בעל העלייה בונה את הבית ודר בתוכה,\u0004 בבית, \u0003עד שיתן לו את יציאותיו (\u0004הוצאותיו) שהוציא על הבית, ויוכל לבנות עלייה.","\u0003ר' יהודה אומר:\u0004 הרי \u0003אף זה,\u0004 בעל העלייה, \u0003דר\u0004 בינתים \u0003בתוך של חבירו,\u0004 ואם כן \u0003צריך להעלות לו שכר\u0004 על שדר בדירתו, ואין זה תיקון נכון. \u0003אלא, בעל העלייה בונה את הבית ואת העלייה, מקרה את העליונה,\u0004 כלומר, גומר את בנין העלייה כל צרכה \u0003ויושב בבית עד שיתן לו את יציאותיו\u0004 שהוציא בבנין הבית ואז יחזור וידור בעלייה."],["\u0003אמר\u0004 \u0003ר' יוחנן: בשלשה מקומות שנה לנו\u0004 \u0003ר' יהודה\u0004 (כלומר, למדים אנו מדבריו) את העקרון ש\u0003אסור לאדם שיהנה מממון חבירו\u0004 אם החבר אינו נותן לו את הדבר מדעתו. \u0003חדא\u0004 \u0005[אחד]\u0006 — \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנתנו\u0005]\u0006 שלא ידור בדירת חבירו בלי לשלם.","\u0003אידך מה היא\u0004 \u0005[האחרת מה היא\u0006\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנותן צמר לצבע לצבוע לו\u0004 את הצמר בצבע \u0003אדום וצבעו\u0004 בצבע \u0003שחור,\u0004 או לצבעו \u0003שחור וצבעו אדום,\u0004 \u0003ר' מאיר אומר: נותן לו\u0004 הצבע, לבעל הצמר \u0003דמי צמרו\u0004 — שהאומן צריך להחזיר צמר חדש ולבן לבעל הצמר. \u0003ר' יהודה אומר:\u0004 אומדים \u0003אם השבח,\u0004 עליית ערך הצמר על ידי הצביעה \u0003יותר על ההוצאה\u0004 שהוציא בצבעים — \u0003נותן לו\u0004 בעל הצמר לאומן את \u0003היציאה\u0004 (הוצאה) בלבד, \u0003ואם ההוצאה יתירה על השבח\u0004 — \u0003נותן לו את השבח.\u0004 אבל אין האומן לוקח לעצמו את הצמר הצבוע, לפי שאסור לו להנות בממון חבירו.","\u0003ואידך מאי היא\u0004 \u0005[ואחרת מה היא\u0006\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שפרע מקצת חובו והשליש את שטרו (\u0004נתן את השטר בידי שלישי, אדם נאמן) \u0003ואמר לו\u0004 החייב לנאמן: \u0003\"אם אין אני נותן לך מכאן ועד זמן פלוני\u0004 — \u0003תן לו שטרו\".\u0004 כלומר, שיוכל המלוה לגבות את מלוא הסכום הכתוב בשטר בלא לנכות מה ששולם כבר. אם \u0003הגיע\u0004 ה\u0003זמן\u0004 שקבע \u0003ולא נתן\u0004 את שאר חובו, \u0003ר' יוסי אומר: יתן\u0004 הנאמן, ו\u0003ר' יהודה אומר: לא יתן\u0004 הנאמן, ואף כאן הטעם הוא שאסור למלוה להנות מממון שאינו שלו.","את הראיות הללו לשיטת \u0003ר'\u0004 יהודה דוחים: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 פירש כך? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה הכא\u0004 \u0005[כאן\u0006\u0005,\u0006 במשנתנו\u0005]\u0006 בענין בית ועלייה, \u0003אלא משום דאיכא שחרוריתא\u0004 \u0005[שיש שחרורית\u0006\u0005],\u0006 שהרי כאשר משתמש בבית משחירים כתליו והוא פוחת קצת בערכו, והרי הדייר לבסוף יגבה דמי בית חדש, ומטעם זה אסור להשתמש בבית בלא לשלם,","\u0003אי נמי\u0004 \u0005[או גם כן\u0006\u0005]\u0006 אפשר להסביר בענין \u0003\"לצבוע לו אדום וצבעו שחור\"\u0004 טעמו של ר' יהודה הוא \u0003משום דקא\u0004 \u0005[שהוא]\u0006 \u0003משנה\u0004 מרצון בעל הבית, \u0003והתנן\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל המשנה ידו על התחתונה.\u0004","\u0003ומי שפרע מקצת חובו נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 אינו מן הטעם שאמרנו, אלא מפני שהחזרת כל השטר כשלא פרע בזמנו \u0003הוי\u0004 \u0005[הריהי]\u0006 כ\u0003אסמכתא\u0004 שאדם מקבל על עצמו תנאי מוגזם שהוא מקוה שלא לקיימו, \u0003ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' יהודה\u0004 ש\u0003אמר לא קני\u0004 \u0005[\u0006ש\u0005אין\u0006 אדם \u0005קונה]\u0006 באסמכתא. ואם כן, אין הוכחה כלל ש\u0003ר'\u0004 יהודה סבור שאסור לאדם להנות מממון חבירו.","\u0003אמר רב אחא בר אדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: תחתון\u0004 בעל הבית, שנפל ורוצים עתה לבנותו מחדש, \u0003הבא לשנות\u0004 ורוצה לבנות \u0003בגויל,\u0004 באבנים גסות וגדולות יותר מכפי שהיו בתחילה — \u0003שומעין לו,\u0004 שהרי הוא רק מועיל לדייר בעלייה, שהרי היסוד של העלייה, שהוא הבית, יהיה בסופו של דבר חזק יותר. ואם היה הבית בנוי מתחילה בגויל ורצה לבנות \u0003בגזית,\u0004 שהם אבנים דקות (ומסותתות) יותר — \u0003אין שומעין לו,\u0004 לפי שמפחית מחוזק הבנין, וכן אם היה בית בנוי בלבנים ורצה לבנות","\u0003בכפיסין\u0004 שהוא קיר לבנים עבה — \u0003שומעין לו,\u0004 היה בנוי בכפיסים ורוצה \u0003בלבנים\u0004 — \u0003אין שומעין לו.\u0004 רצה \u0003לסכך\u0004 את התקרה \u0003בארזים\u0004 שהם חזקים יותר — \u0003שומעין לו, בשקמים\u0004 במקום ארזים — \u0003אין שומעין לו.\u0004","רצה \u0003למעט בחלונות\u0004 — \u0003שומעין לו\u0004 שהרי על ידי כך מתחזקים הכתלים, \u0003להרבות בחלונות\u0004 — \u0003אין שומעין לו. להגביה\u0004 — \u0003אין שומעין לו\u0004 שמא על ידי כך לא יהא הבנין יציב כמקודם. \u0003למעט\u0004 בגובה — \u0003שומעין לו.\u0004","ולהיפך, \u0003עליון שבא לשנות\u0004 מן הבנין הקודם אם רצה לשנות מגויל ורוצה לבנות \u0003בגזית\u0004 שהיא דקה יותר — \u0003שומעין לו,\u0004 שהרי הוא מפחית מן העומס על הדירה התחתונה. רצה לשנות מגזית ל\u0003גויל\u0004 — \u0003אין שומעין לו,\u0004 שהרי בכך הוא מכביד על הבית.","רצה לשנות מלבנים ל\u0003כפיסים\u0004 — \u0003אין שומעין לו,\u0004 ואם רצה לשנות ל\u0003לבנים\u0004 — \u0003שומעין לו.\u0004 רצה לקרות את ביתו \u0003בארזים\u0004 שהם כבדים יותר — \u0003אין שומעין לו,\u0004 רצה לקרות \u0003בשקמה\u0004 במקום ארז — \u0003שומעין לו.\u0004 רצה \u0003לרבות בחלונות\u0004 שממעיט בכך ממשקל הבית — \u0003שומעין לו. למעט בחלונות\u0004 — \u0003אין שומעין לו. להגביה\u0004 — \u0003אין שומעין לו\u0004 לפי שמכביד את הבנין, \u0003למעט\u0004 — \u0003שומעין לו.\u0004","שואלים: אם שני בעלי הבית אינם בעלי הקרקע, והם עניים ו\u0003אין לו לזה\u0004 כסף לבנות, \u0003ולא לזה\u0004 ואינם יכולים לבנות, ובעל הקרקע מוכן לפצותם שיעקרו לגמרי מן המקום, \u0003מאי\u0004 \u0005[מה\u0006 הדין \u0005]?\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין לו לא לזה ולא לזה\u0004 — \u0003אין לו לבעל\u0004 ה\u0003עלייה בקרקע כלום\u0004 וכל זכויות הבנין הן לבעל הקומה התחתונה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003ר' נתן אומר: תחתון נוטל שני חלקים\u0004 מן הקרקע \u0003והעליון שליש. ואחרים אומרים: תחתון נוטל שלשה חלקים והעליון נוטל רביע. אמר רבה: נקוט\u0004 \u0005[החזק\u0006\u0005]\u0006 בשיטת \u0003ר' נתן בידך, דדיינא\u0004 \u0005[שדיין]\u0006 \u0003הוא ונחית לעומקא דדינא\u0004 \u0005[ויורד לעומק הדין\u0006\u0005],\u0006 וטעמו — \u0003קא סבר\u0004 \u0005[סבור הוא\u0006\u0005]:\u0006 \u0003כמה מפסיד,\u0004 כלומר, כמה הפסד יש כתוצאה מהיות ה\u0003עלייה\u0004 על גבי ה\u0003בית\u0004 בחוזקו ובשימושו — \u0003תילתא\u0004 \u0005[שליש\u0006\u0005]\u0006 ולכן \u0003אית ליה תילתא\u0004 \u0005[יש לו שליש\u0006\u0005],\u0006 שראוי לו לקבל שליש מן הסכום הכולל שמקבלים עבור הבית.","\u0003וכן בית הבד שהוא בנוי\u0004 במערה \u0003בסלע וגינה אחת\u0004 של אחר נטועה \u0003על גביו, ונפחת\u0004 בית הבד והגינה שקעה למטה — \u0003הרי בעל הגינה יורד וזורע למטה עד שיעשה\u0004 אותו אדם \u0003לבית בדו כיפין\u0004 (בנין על קשתות), ויחזק את כיפת בית הבד, ויוכל בעל הגינה לזרוע למעלה.","ודין אחר הקשור במפולת: \u0003הכותל והאילן שנפלו לרשות הרבים והזיקו\u0004 שם — \u0003פטור\u0004 בעליהם \u0003מלשלם,\u0004 שהרי אונס הוא. ראו בית הדין שהכותל רעוע והאילן נוטה, ו\u0003נתנו לו זמן לקוץ את האילן,\u0004 או \u0003לסתור את הכותל ונפלו,\u0004 אם נפלו \u0003בתוך הזמן\u0004 שנתנו לו — \u0003פטור, לאחר הזמן\u0004 — \u0003חייב,\u0004 שהרי לשם כך הזהירוהו.","\u0003מי שהיה כותלו סמוך לגינת חבירו ונפל, ואמר לו\u0004 בעל הגינה: \u0003פנה\u0004 את \u0003אבניך, ואמר לו\u0004 בעל הכותל־האבנים:"],["\u0003הגיעוך,\u0004 הרי הן שלך, כלומר אני מפקיר אותן ואתה יכול לקחת אותם לעצמך — \u0003אין שומעין לו,\u0004 שאינו יכול לכפות על האחר לקחת את האבנים. \u0003משקבל עליו,\u0004 אם הסכים בעל הגינה לקבל את האבנים, ולבסוף \u0003אמר לו\u0004 בעל האבנים: \u0003הילך את יציאותיך\u0004 (הוצאותיך) לפינויין, \u0003ואני אטול את\u0004 האבנים \u0003שלי\u0004 — \u0003אין שומעין לו,\u0004 שהרי נתן לחבירו הכל במתנה.","ועוד דין דומה: \u0003השוכר את הפועל לעשות\u0004 (לעבוד) \u0003עמו בתבן\u0004 או \u0003בקש, ו\u0004לאחר שסיים מלאכתו \u0003אמר לו\u0004 הפועל לבעל הבית: \u0003תן לי שכרי. ואמר לו\u0004 בעל הבית: \u0003טול מה שעשית בשכרך,\u0004 כלומר, קח לך מן התבן והקש ויהא זה שכרך — \u0003אין שומעין לו.\u0004 ואולם \u0003משקבל עליו\u0004 הפועל והסכים לקחת תבן, ואחר כך התחרט בעל הבית \u0003ואמר לו: הילך שכרך ואני אטול את שלי\u0004 — \u0003אין שומעין לו,\u0004 שכבר קנה הפועל את התבן לעצמו.","מה שאמרנו ש\u0003נפחתה\u0004 קרקעית הגינה נחלקו אמוראים בשיעור שנפחתה, \u0003רב אמר\u0004 שנפחתה \u0003ברובה, ושמואל אמר\u0004 שנפחתה \u0003בארבע\u0004 אמות, ומסבירים טעמיהם: \u0003רב אמר: ברובה, אבל בארבע\u0004 אמות עדיין אין זה מקום לתביעה, כי \u0003אדם זורע חציו\u0004 (כלומר, חלק) \u0003למטה וחציו למעלה. ושמואל אמר: בארבע\u0004 אמור, כי \u0003אין אדם זורע חציו למטה וחציו למעלה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך\u0006\u0005]\u0006 שתיאמר מחלוקתם של רב ושמואל גם כאן וגם בעין דירה שנפחתה. \u0003דאי אשמועינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק בענין \u0003דירה,\u0004 היינו אומרים כי \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שכך הדין \u0003משום דלא עבידי אינשי דדיירי פורתא הכא ופורתא הכא\u0004 \u0005[שאין אנשים עשויים שיגורו מעט כאן ומעט כאן\u0006\u0005],\u0006 \u0003אבל לענין זריעה\u0004 — \u0003עבידי אינשי דזרעי הכא פורתא והכא פורתא\u0004 \u0005[עשויים בני אדם שיזרעו כאו מעט וכאן מעט\u0006\u0005],\u0006 ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 שאולי הוא \u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב\u0004 בענין זה. \u0003ואי איתמר בהך\u0004 \u0005[ואילו נאמר רק בזו,\u0006 בגינה \u0005],\u0006 היינו אומרים: \u0003בהך קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אמר]\u0006 \u0003רב\u0004 מה שאמר, \u0003אבל בהא\u0004 \u0005[בזו\u0006 שבדירה \u0005]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שאולי הוא \u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 שתיאמר המחלוקת בשני המקרים.","שנינו במשנה שאם \u0003נתנו לו זמן\u0004 לקצוץ ונפל, יש הבדל להלכה בין אם נפל בתוך הזמן או לאחריו. ושואלים: \u0003וכמה זמן\u0004 נותן \u0003בית דין\u0004 כרגיל? \u0003אמר\u0004 \u0003ר' יוחנן:\u0004 בדרך כלל \u0003שלשים יום\u0004 שנותנים בית דין לאדם לסדר את ענייניו.","שנינו במשנה בענין \u0003מי שהיה כותלו\u0004 סמוך לגינת חבירו ונפל, שאם אמר בעל הכותל לבעל הגינה על אבני הכותל \"הגיעוך\" — אינו יכול לחזור בו. ומעירים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנינו בסוף\u0006 המשנה \u0005]\u0006 בענין שאמר בעל הכותל \u0003\"הילך יציאותיך\", מכלל\u0004 הדבר אתה למד שבמקרה \u0003דפנינהו עסקינן\u0004 \u0005[ש\u0006בעל הגינה \u0005פינה אותן,\u0006 את האבנים\u0005, עוסקים אנו].\u0006 ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא — \u0003דפנינהו\u0004 \u0005[\u0006\u0005שפינה אותן\u0006\u0005],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא פנינהו\u0004 \u0005[פינה אותן]\u0006 — \u0003לא,\u0004 ועדיין הן נחשבות כשייכות לבעל הכותל.","ותוהים: \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 צריך שיעשה בהן מעשה? \u0003ותקנה ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003שדהו\u0004 לבעל הגינה את האבנים, שמכוח העובדה שהאבנים נפלו בשדהו — קנה אותן, ואינו צריך קנין נוסף, שהרי \u0003אמר\u0004 \u0003ר' יוסי ב\u0004\u0003ר' חנינא: חצירו של אדם קונה לו\u0004 חפצים הנכנסים לתוכה אפילו \u0003שלא מדעתו!\u0004","ומשיבים: \u0003הני מילי היכא דקא מיכוין לאקנויי ליה\u0004 \u0005[דברים אלה אמורים במקום,\u0006 במקרה שהנותן מתכוון \u0005להקנות לו\u0006\u0005],\u0006 שאז קונה השדה אותם בלי צורך בקנין נוסף. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 — \u0003אישתמוטי\u0004 \u0005[להשתמט]\u0006 \u0003הוא דקא מישתמיט ליה\u0004 \u0005[ש\u0006הוא \u0005משתמט לו\u0006\u0005],\u0006 לפי שרוצה שבעל הגינה יטפל באבנים, ואז יוכל הוא לקבלן ממנו בלא לטרוח הרבה.","שנינו בענין \u0003השוכר\u0004 פועל \u0003לעשות עמו בתבן\u0004 ותבע \u0003ממנו הפועל את שכרו, ואמר לו בעל הבית שיטול את מה שעשה בשכרו\u0004 — אין שומעים לו. ומעירים: \u0003וצריכא\u0004 \u0005[ונצרכה\u0006\u0005]\u0006 הלכה זו להיאמר, אף שלכאורה היא דומה להלכה הקודמת.","\u0003דאי אשמועינן להך קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005את זו הראשונה\u0006 באבנים שנפלו \u0005],\u0006 \u0003דכי קאמר ליה\u0004 \u0005[שכאשר אמר לו]\u0006 \u0003\"הגיעוך\"\u0004 \u0003אין שומעין לו,\u0004 היינו אומרים שהדין כך \u0003משום דלית ליה אגרא גביה\u0004 \u0005[שאין לו שכר אצלו\u0006\u0005],\u0006 כלומר, אין ביניהם משא ומתן ואין לבעל הגינה כל התחייבות או קשר לבעל האבנים, \u0003אבל הכא, דאית ליה אגרא גביה, אימא\u0004 \u0005[כאן שיש לו שכר אצלו, אמור\u0006\u0005]\u0006 ש\u0003שומעים לו,\u0004 והטעם — \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]\u0006 בפתגם עממי: \u0003ממרי רשותיך פארי אפרע\u0004 \u0005[מבעל חובך תבן הפרע\u0006\u0005],\u0006 כלומר, קח כל מה שתוכל לקחת.","\u0003ואי אשמועינן\u0004 \u0005[אם היה משמיע לנו כאן\u0006\u0005]\u0006 בענין התבן, הייתי אומר: דווקא \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 \u0003שמשקבל עליו אין שומעין לו,\u0004 ומדוע — \u0003משום דאית ליה אגרא גביה\u0004 \u0005[שיש לו שכר אצלו\u0006\u0005],\u0006 ולכן יש טעם לומר שמגיע לו את התבן, \u0003אבל הכא דלית ליה אגרא גביה, אימא\u0004 \u0005[כאן\u0006 באבנים \u0005שאין לו שכר אצלו, אמור\u0006\u0005]\u0006 ש\u0003שומעין לו\u0004 ויכול לחזור בו, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר כן בשני הנושאים.","שנינו במשנה שהמשלם לפועל בתבן — \u0003אין שומעין לו.\u0004 ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא \u0005]\u0006 להלכה ש\u0003שומעין לו!\u0004 \u0003אמר רב נחמן: לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005];\u0006 \u0003כאן\u0004 במשנתנו ששנינו שאין שומעים לו מדובר כשעשה הפועל עבודה \u0003בשלו, כאן\u0004 ששנינו בברייתא ששומעים לו הרי זה כשעשה בשל \u0003חבירו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 הרי \u0003בשלו מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]\u0006 אין שומעים לו — משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הפועל: \u0003אגרא עלך\u0004 \u0005[השכר עליך\u0006\u0005],\u0006 ואם כן \u0003בשל חבירו\u0004 הרי \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003שכרו עליו. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוכר את הפועל לעשות בשלו,\u0004 ובמקום זה \u0003הראהו\u0004 לעשות \u0003בשל חבירו\u0004 — \u0003נותן לו\u0004 לפועל שכרו \u0003משלם, וחוזר ונוטל מבעל הבית מה שההנה אותו\u0004 בעבודת הפועל. ואם כן אין מבחינתו של הפועל הבדל אם עשה בשלו או בשל חבירו!","\u0003אלא\u0004 \u0003אמר רב נחמן,\u0004 יש לחזור מן ההסבר הקודם, ולומר כך: \u0003לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005];\u0006 \u0003כאן\u0004 כשעובד הפועל בתוך \u0003שלו\u0004 של בעל הבית אין שומעים לו, \u0003כאן\u0004 כשעובד \u0003בשל הפקר\u0004 כגון ששכרו לאסוף תבן מן ההפקר, ולבסוף אמר לו: קח לך את התבן לעצמך, שומעים לו.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003רבא לרב נחמן\u0004 הלא שנינו: \u0003מציאת פועל\u0004 — \u0003לעצמו, אימתי\u0004 — \u0003בזמן שאמר לו בעל הבית\u0004 לעשות לו מלאכה מסויימת כגון \u0003נכש עמי היום, או עדור עמי היום,\u0004 שאם מצא מציאה בנוסף לעבודה שעבד — המציאה שלו. ואף כאן כיון ששכר את הפועל לאסוף קש — נקנה הקש לבעל הבית והריהו שלו, \u0003אבל אם אמר לו\u0004 סתם: \u0003עשה עמי מלאכה היום\u0004 — \u0003מציאתו לבעל הבית.\u0004 ואם כן נמצא שעבד הפועל בשל בעל הבית!","\u0003אלא אמר רב נחמן:\u0004 אפשר לומר שבשני המקרים מדובר ששכרו לעשות בהפקר, ו\u0003לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005];\u0006 \u0003כאן\u0004 במשנה האומרת שאין שומעים לו מדובר \u0003בהגבהה,\u0004 שמלאכתו היתה להגביה את התבן או לאספו, שעל ידי כן נעשה כשליחו של בעל הביתן וכאילו עובד בשבילו. \u0003כאן\u0004 בברייתא האומרת ששומעים לו — הרי זה \u0003בהבטה\u0004 בלבד, וכגון ששכרו לשמור שלא יקחו אחרים תבן וקש של הפקר, שאז לא קנה אותם אף בעל הבית בעצמו, ונמצא שהכל הפקר ויכול לומר לפועל שיזכה בתבן זה.","\u0003אמר רבה\u0004 השאלה לגבי \u0003הבטה\u0004 אם היא קונה \u0003בהפקר\u0004 — \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא.\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שומרי ספיחי שביעית\u0004 שהיו מציבים שומרים בשנת השמיטה על התבואה הצומחת מעצמה (ספיחים) כדי שתשאר תבואה שיוכלו להקריב ממנה את העומר ושתי הלחם, שומרים אלה \u0003נוטלין שכרן מתרומת הלשכה,\u0004 מכספי בית המקדש, כשאר צורכי המקדש. \u0003ר' יוסי אומר:\u0004 אין חובה לשכור שומרים, ו\u0003הרוצה מתנדב הוא ושומר חנם. אמרו לו: אתה אומר כן?\u0004 אם כן \u0003אין באין משל צבור,\u0004 שלשיטתך בעצם היחיד, השומר, הוא המביא את העומר.","ומציעים: \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה נחלקו\u0006\u0005]:\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור\u0006\u0005]\u0006 ש\u0003הבטה בהפקר קני\u0004 \u0005[קונה\u0006\u0005],\u0006 שהשומר דבר של הפקר, אף שלא הגביהו, קנה אותו לעצמו, \u0003ו\u0004לכן \u0003אי יהיבי ליה אגרא\u0004 \u0005[אם נותנים לו שכר\u0006\u0005]\u0006 משל הציבור, נמצא ששומר (וקונה) עבור הציבור — \u0003אין\u0004 \u0005[כן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 נותנים לו שכר — \u0003לא,\u0004 אלא קנאו לעצמו בלבד. \u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 ש\u0003הבטה בהפקר לא קני\u0004 \u0005[אינה קונה\u0006\u0005]\u0006 \u0003וכי אזלי\u0004 \u0005[וכאשר הולכים]\u0006 ה\u0003צבור ומייתי\u0004 \u0005[ומביאים]\u0006 את השעורים לעומר או את החיטים לשתי הלחם — \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דקא זכי ביה\u0004 \u0005[שהם זוכים בו\u0006\u0005].\u0006","\u0003ומה\u0004 משמעות \u0003\"אתה אומר\u0004 כן \u0003\"\u0004שבמשנה זו — יש להבין כי \u0003הכי קאמרי ליה\u0004 \u0005[כך אומרים לו\u0006\u0005]:\u0006 \u0003מדבריך לדברינו,\u0004 אם נצרף את הדרך שאתה מציע, לפי השיטה שלנו בהלכות קנין ההפקר — נמצא ש\u0003אין עומר ושתי לחם באין משל צבור.\u0004","\u0003אמר רבא: לא,\u0004 את ההוכחה הזו אפשר לדחות, ולפרש הכל אחרת. כלומר, \u0003דכולי עלמא\u0004 \u0005[שלכל העולם,\u0006 לדעת הכל\u0005]\u0006 \u0003הבטה בהפקר קני\u0004 \u0005[קונה],\u0006 \u0003והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 מחלוקת בנושא אחר היא; בשאלה האם \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא לא ימסרם יפה יפה\u0004 לציבור \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003יהבינן ליה אגרא\u0004 \u0005[\u0006ש\u0005נותנים לו\u0006 לשומר \u0005שכר\u0006\u0005]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יתנו לו שכר אלא הוא מתנדב באפן כזה \u0003חיישינן\u0004 \u0005[חוששים אנו\u0006\u0005]\u0006 \u0003שמא לא ימסרם\u0004 לציבור \u0003יפה יפה,\u0004 שיהא בלבו שבעצם התבואה שייכת לו והוא הוא שמקריבה משלו, ואם כן אין זה ממש משל צבור.","\u0003ר' יוסי סבר\u0004 \u0005[סבור]\u0006 ש\u0003לא חיישינן\u0004 \u0005[איננו חוששים\u0006\u0005]\u0006 \u0003שמא לא ימסרם\u0004 לציבור \u0003יפה יפה, ומה \"אתה אומר\u0004 כן \u0003\"\u0004הכתוב במשנה — יש להבין כי \u0003הכי קאמרי ליה\u0004 \u0005[כך אומרים\u0006 הם \u0005לו\u0006\u0005]:\u0006 \u0003מדבריך,\u0004 לשיטתך שאפשר להתנדב, \u0003לדברינו דחיישינן\u0004 \u0005[שאנו חוששים\u0006\u0005]\u0006 \u0003שמא לא ימסרם יפה יפה,\u0004 אם כן \u0003אין עומר ושתי לחם באין משל צבור.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים\u0006\u0005]\u0006 בלשון אחרת: \u0003רבא אמר: דכולי עלמא\u0004 \u0005[לכל העולם,\u0006 לדעת הכל \u0005]\u0006 \u0003הבטה בהפקר לא קני\u0004 \u0005[אינה קונה\u0006\u0005],\u0006 \u0003והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 לענין העומר השאלה אם \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לבעלי זרועות קמיפלגי\u0004 \u0005[חולקים\u0006\u0005],\u0006 האם חוששים שיבואו אנשים אלימים ויקחו תבואה זו לעצמם, או לא. שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור\u0006\u0005]\u0006 \u0003דתקינו רבנן למיתב ליה ארבע זוזי\u0004 \u0005[שתיקנו חכמים לתת לו ארבעה זוזים\u0006\u0005],\u0006 או שכר אחר לפי הענין כשכר שמירה, \u0003כי היכי דלישמעי\u0004 \u0005[כדי שישמעו]\u0006 \u0003בעלי זרועות וליפרשו מינייהו\u0004 \u0005[ויפרשו מהן\u0006\u0005]\u0006 כי כאשר השומר מודיע שהוא של הקדש ודאי לא יקחו. \u0003ו\u0004\u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003לא תקינו\u0004 \u0005[תיקנו\u0006\u0005]\u0006 דבר זה, שאין חוששים לכך, ואף אדם פרטי יכול לשמור את התבואה בלא שיקחו ממנו."],["\u0003ומה \"אתה אומר\u0004 כן \u0003\"\u0004— יש להסביר כי \u0003הכי קאמרי ליה\u0004 \u0005[כך אמרו לו\u0006\u0005]:\u0006 \u0003מדבריך לדברינו אין באין משל צבור. וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: חוששין לבעלי זרועות איכא בינייהו\u0004 \u0005[יש ביניהם\u0006\u0005],\u0006 כלומר, בענין זה נחלקו.","\u0003המוציא זבל לרשות הרבים\u0004 כדי לשאתו למקום אחר, \u0003המוציא\u0004 — \u0003מוציא, והמזבל\u0004 — \u0003מזבל,\u0004 שאינו רשאי לשהות את הזבל ברשות הרבים, אלא אחד מוציא והשני מעביר מיד את הזבל למקומו. וכן \u0003אין שורין טיט\u0004 לגבל \u0003ברשות הרבים, ואין לובנים לבנים\u0004 ברשות הרבים. \u0003אבל גובלין טיט ברשות הרבים\u0004 שדבר זה נעשה בתוך זמן קצר, \u0003אבל לא\u0004 גובלין \u0003לבנים,\u0004 שדבר זה לוקח זמן רב, ומבטל את רשות הרבים מבעליה.","\u0003הבונה ברשות הרבים; המביא אבנים\u0004 — \u0003מביא, והבונה\u0004 — \u0003בונה\u0004 אותן מיד, ואינו משאירן שם. \u0003ואם הזיק\u0004 — \u0003משלם מה שהזיק. רבן שמעון בן גמליאל אומר: אף מתקן הוא את מלאכתו לפני שלשים יום,\u0004 כלומר, רשאי להכין למלאכת הבניה תוך כל שלושים יום לבניה.","שואלים: \u0003לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו\u0006\u0005]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בשעת הוצאת זבלים אדם מוציא זבלו לרשות הרבים וצוברו כל שלשים יום, כדי שיהא נישוף\u0004 (נדרס) \u0003ברגלי אדם וברגלי בהמה\u0004 ונעשה מוכן לזבל בו, \u0003שעל מנת כן הנחיל יהושע לישראל את הארץ.\u0004 כלומר, דבר זה הוא חלק מן ההסכמה הכללית של כל ישראל, שיוותרו במקצת זה לזה על זכויותיהם.","ומשיבים: \u0003אפילו תימא:\u0004 \u0005[תאמר\u0006\u0005]\u0006 שמשנתנו כשיטת \u0003ר' יהודה,\u0004 מכל מקום \u0003מודה\u0004 \u0003ר' יהודה ש\u0004אף שעשה זאת ברשות, \u0003אם הזיק\u0004 — \u0003חייב לשלם.\u0004 ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה \u0005]:\u0006 \u0003מודה\u0004 \u0003ר' יהודה בנר חנוכה\u0004 שהניחו אדם ברשות הרבים וכתוצאה ממנו אירעה דליקה \u0003ונזוקו חפצים\u0004 \u0003שהוא פטור,\u0004 \u0003מפני שהוא עושה ברשות. מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 מפני שיש בכך \u0003רשות בית דין\u0004 לעשות שימוש זה ברשות הרבים. ומכאן שלדעתו אם עשה ברשות בית דין — פטור מנזקין? ודוחים: \u0003לא,\u0004 שם יש \u0003רשות\u0004 של \u0003מצוה,\u0004 שהרי המצוה היא להניח נר חנוכה בחוץ ומשום כך פטור. אבל אם עושה דבר שאינו מצוה — חייב לשלם מה שהזיק.","ומקשים ממה ששנינו במקור אחר, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל אלו שאמרו\u0004 חכמים שהם \u0003מותרין לקלקל ברשות הרבים,\u0004 מכל מקום \u0003אם הזיק\u0004 — \u0003חייב לשלם, ו\u0004\u0003ר' יהודה פוטר.\u0004 הרי שהוא סבור שבמקום שיש לו רשות פטור מלשלם! \u0003אלא מחוורתא, מתניתין\u0004 \u0005[מחוור שמשנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' יהודה.\u0004","\u0003אמר אביי:\u0004 \u0003ר' יהודה, ורבן שמעון בן גמליאל, ור' שמעון כולהו סבירא להו\u0004 \u0005[כולם סבורים הם\u0006\u0005]\u0006 בשיטה אחת: \u0003כל מקום שנתנו לו חכמים\u0004 לאדם \u0003רשות\u0004 לעשות דבר מה \u0003והזיק\u0004 על ידי כך — \u0003פטור.\u0004 \u0003ר' יהודה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו\u0006\u0005].\u0006 \u0003רבן שמעון בן גמליאל\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה \u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: אף מתקן הוא את מלאכתו לפני שלשים יום.\u0004","\u0003ר' שמעון\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה \u0005]:\u0006 \u0003היה מעמידו\u0004 את התנור \u0003בעלייה\u0004 — \u0003צריך שיהא תחתיו מעזיבה\u0004 (טיט של כיסוי התקרה) בעובי \u0003שלשה טפחים,\u0004 שאם לא כן יתכן שהתנור, על ידי החום שבו, ישרוף את הקורות ויזיק בדירה התחתונה, \u0003ו\u0004אם היתה זו \u0003כירה\u0004 שהיא קטנה והאש בה מעטה — דיו במעזיבה בעובי של \u0003טפח.\u0004 \u0003ו\u0004מכל מקום \u0003אם הזיק\u0004 בכל זאת — \u0003משלם מה שהזיק.\u0004 \u0003ר' שמעון אומר: לא\u0004 הדגישו ו\u0003אמרו\u0004 חכמים את \u0003כל השעורים הללו אלא\u0004 לומר \u0003שאם הזיק פטור מלשלם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003החצב\u0004 (חוצב אבנים) \u0003שמסר\u0004 אבנים \u0003לסתת,\u0004 מאותה השעה \u0003הסתת חייב\u0004 באחריות נזקיהן. \u0003הסתת שמסר לחמר\u0004 להביא לבנין — מאז \u0003החמר חייב\u0004 באחריות נזקיהן. \u0003החמר שמסר לכתף\u0004 (סבל) שהוא מביא את האבנים לבנין — \u0003הכתף חייב. הכתף שמסר לבנאי\u0004 — \u0003הבנאי חייב, הבנאי שמסר לאדריכל,\u0004 שהוא זה שמעמיד ממש ומיישר את האבנים בבנין — ה\u0003אדריכל חייב. ואם הניח אבן על הדימוס\u0004 (נדבך) \u0003והזיקה\u0004 האבן בנפילה — \u0003כולן חייבין לשלם.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא \u0005]\u0006 שה\u0003אחרון,\u0004 כלומר, האדריכל שהוא האחרון \u0003חייב וכולן,\u0004 של השאר שלפניו \u0003פטורים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה\u0006\u0005];\u0006 \u0003כאן בשכירות\u0004 שאז האחרון חייב, \u0003כאן בקבלנות\u0004 שקיבלו כולם יחד את העבודה, ולכן כולם חייבים לשלם.","\u0003שתי גנות\u0004 שהיו \u0003זו על גב זו,\u0004 שאחת היתה במקום נמוך והשניה בחצר סמוכה וגבוהה, והיה \u0003ירק\u0004 צומח \u0003בינתים\u0004 בגובה הכותל שבין הגינות, \u0003ר' מאיר אומר:\u0004 ירק זה \u0003של\u0004 ה\u0003עליון,\u0004 \u0003ר' יהודה אומר: של\u0004 ה\u0003תחתון. אמר\u0004 \u0003ר' מאיר\u0004 להצדיק את שיטתו: והלא \u0003אם ירצה העליון\u0004 לחפור ו\u0003ליקח את עפרו,\u0004 אם כן \u0003אין כאן ירק,\u0004 ואם כן ודאי ששלו הוא. ומאידך \u0003אמר\u0004 \u0003ר' יהודה:\u0004 והלא \u0003אם ירצה התחתון למלאות את גנתו\u0004 בעפר ולהגביהה, גם אז \u0003אין כאן ירק,\u0004 ואם כן ודאי ששלו הוא.","\u0003אמר\u0004 \u0003ר' מאיר: מאחר ששניהן יכולים למחות זה על זה,\u0004 והרשות בידם לעשות שלא יהא ירק זה קיים, אין ללמוד מכך דבר לענין זכותם אלא \u0003רואים מהיכן ירק זה חי,\u0004 כלומר, להיכן פונים שורשיו ומהיכן הם יונקים, אם מלמעלה או מלמטה. \u0003אמר\u0004 \u0003ר' שמעון,\u0004 כך יש לעשות: \u0003כל שהעליון יכול לפשוט את ידו וליטול\u0004 מן הירק — \u0003הרי הוא שלו, והשאר של\u0004 ה\u0003תחתון.\u0004","\u0003אמר רבא: בעיקרו,\u0004 בענין שרשו של הירק (כגון שהיתה זו לפת הצומחת בתוך האדמה), \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל\u0006 אינם חלוקים] של \u0003עליון הוי\u0004 \u0005[הוא\u0006 שייך\u0005],\u0006 שהרי הקרקע ודאי של העליון היא. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו\u0006\u0005]\u0006 הרי זה \u0003בנופו\u0004 הצומח בתוך חלל החצר התחתונה. \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003שדי\u0004 \u0005[זרוק\u0006\u0005,\u0006 החשב\u0005]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר\u0006\u0005]\u0006 \u0003עיקרו,\u0004 והכל הולך לפי העיקר. ו\u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים\u0006\u0005]\u0006 \u0003שדי\u0004 \u0005[זרוק,\u0006 החשב\u0005]\u0006 את \u0003נופו בתר\u0004 \u0005[אחר\u0006\u0005]\u0006 \u0003עיקרו.\u0004","ומעירים: \u0003ואזדא לטעמייהו\u0004 \u0005[והולכים\u0006 הם \u0005לטעמם,\u0006 לשיטתם\u0005]\u0006 כפי שבוטאה במקום אחר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 לגבי עץ השייך לאדם אחד, הגדל בקרקעו של אדם אחר, ש\u0003היוצא מן הגזע ומן השרשין\u0004 — \u0003הרי אלו של בעל הקרקע,\u0004 אלו \u0003דברי\u0004 \u0003ר' מאיר.\u0004 ומשמע שאף הנוף הצומח הולך אחר השורש. \u0003ר' יהודה אומר:\u0004 מה שיוצא \u0003מן הגזע\u0004 הריהו \u0003של בעל האילן, ו\u0004מה שיוצא \u0003מן השרשין\u0004 הריהו \u0003של בעל הקרקע,\u0004 משמע שהוא סבור שלא הכל הולך אחרי השורש."],["\u0003ותנן נמי גבי\u0004 \u0005[ושנינו גם כן\u0006 משנה \u0005אצל]\u0006 דיני \u0003ערלה כי האי גוונא\u0004 \u0005[כגון זו\u0006\u0005]:\u0006 \u0003אילן היוצא מן הגזע ומן השרשין\u0004 של אילן ישן — \u0003חייב בערלה\u0004 כי דינו כאילן חדש, וצריך למנות לו שנות ערלה מחדש, אלו \u0003דברי\u0004 \u0003ר' מאיר.\u0004 \u0003ר' יהודה אומר:\u0004 אם יצא \u0003מן הגזע\u0004 — \u0003פטור\u0004 שהוא נחשב כענף היוצא מן האילן הישן, ואם יצא \u0003מן השרשין\u0004 — \u0003חייב.\u0004","ומעירים: \u0003וצריכי\u0004 \u0005[ונצרכו\u0006\u0005]\u0006 הדברים להיאמר בכל המחלוקות הללו, אף שלכאורה מדובר באותו עיקרון ממש. \u0003דאי אשמועינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005בראשונה\u0006\u0005]\u0006 במשנתנו, הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר\u0006\u0005]\u0006 \u0003ר' יהודה\u0004 שכך הדין \u0003משום דממונא\u0004 \u0005[ש\u0006הוא ענין \u0005של ממון\u0006\u0005]\u0006 לפשר בין החולקים באופן כזה, \u0003אבל גבי\u0004 \u0005[אצל]\u0006 דיני \u0003ערלה דאיסורא\u0004 \u0005[ש\u0006הוא ענין \u0005של איסור\u0006\u0005]\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה\u0006 הוא \u0005לו\u0006\u0005]\u0006 \u0003ל\u0004\u0003ר' מאיר. ואי איתמר בהא\u0004 \u0005[ואילו נאמר בזו\u0006\u0005]\u0006 בדיני ערלה הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 בלבד \u0005אמר\u0006\u0005]\u0006 \u0003ר' מאיר\u0004 להחמיר, \u0003אבל בההיא,\u0004 בענין ממונות — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה\u0006 הוא \u0005לו]\u0006 \u0003ל\u0004\u0003ר' יהודה,\u0004 על כן \u0003צריכי\u0004 \u0005[נצרכו\u0006\u0005]\u0006 כולם להיאמר.","שנינו במשנה, \u0003אמר\u0004 \u0003ר' שמעון: כל שהעליון יכול לפשוט\u0004 ידיו וליטול — הריהו שלו, והשאר של התחתון. \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 \u0003ובלבד שלא יאנס,\u0004 שלא יתאמץ יותר מדי, אלא כפי שהוא יכול לפשוט את ידו כרגיל.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב ענן, ואיתימא\u0004 \u0005[ויש אומרים\u0006\u0005]\u0006 שהיה זה \u0003ר' ירמיה\u0004 ששאל: אם \u0003מגיע\u0004 העליון \u0003לנופו ואין\u0004 הוא \u0003מגיע לעיקרו\u0004 או שהוא \u0003מגיע לעיקרו ואין\u0004 הוא \u0003מגיע לנופו מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 במקרה זה, האם הוא נחשב כמגיע או כאינו מגיע? לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 במקומה.","\u0003אמר אפרים ספרא\u0004 \u0005[הסופר\u0006\u0005]\u0006 \u0003תלמידו של ריש לקיש משום\u0004 (בשם) \u0003ריש לקיש: הלכה כ\u0004\u0003ר' שמעון.\u0004 \u0003אמרוה,\u0004 את המחלוקת הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך\u0006 הפרסי\u0005]\u0006 שסיפרו לו על בעיה משפטית זו — שכיון שהוא בנושא כללי התענין בה גם המלך הפרסי, ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אפריון נמטייה\u0004 \u0005[שבח מגיע לו]\u0006 \u0003ל\u0004\u0003ר' שמעון.\u0004 כלומר, גם הוא סבר שזאת היא השיטה הנכונה והיפה ביותר.",""]]};
